/* ---------- GCSE Maths: 3. Ratio, Proportion & Rates of Change. Four lists per topic: Easy, Moderate, Difficult, Very Difficult. ---------- */
(()=>{const {add,rd,sf,rat,svgG,crd,mins,pickn,gb,supt,dsp,exStr}=MH;
const X=(q,o,m,w)=>Q(q,o.a,m,w,{d:o.d,alt:o.alt});
const ng=n=>n<0?`(−${-n})`:`${n}`,mn=n=>n<0?`−${-n}`:`${n}`;
const cop=(lo,hi)=>{let a,b;do{a=r(lo,hi);b=r(lo,hi)}while(a==b||gcd(a,b)>1);return[a,b]};
const money=v=>gb(rd(v,2));
const pk=(a,fb)=>a.length?pick(a):fb;   /* pick from a filtered list, or use the fallback if it is empty */

/* ===== Ratio ===== */
add('Ratio, Proportion & Rates of Change','Ratio',[
/* Easy */[
()=>{const [a,b]=cop(1,9);return QF(`Red and blue counters are in the ratio ${a} : ${b}. What fraction of the counters are red? Give it in its simplest form.`,a,a+b,`The ratio has ${a} + ${b} = ${a+b} parts in total. Red is ${a} of those parts.`,`total parts = ${a+b}; red = ${a}/${a+b}`,{fmt:'f'})},
()=>{const [a,b]=cop(1,9),k=r(2,12);const [p1,p2]=who(2);return Q(`${p1} and ${p2} share some money in the ratio ${a} : ${b}. ${p1} gets £${a*k}. How much does ${p2} get (£)?`,b*k,`${p1}'s ${a} parts are worth £${a*k}, so one part is £${k}.`,`1 part = ${a*k} ÷ ${a} = ${k}; ${p2} = ${b} × ${k} = ${b*k}`)},
()=>{const g=r(2,8),[a,b]=cop(1,9),c=r(1,9);const gg=gcd(gcd(a,b),c);return X(`Simplify the ratio ${a*g} : ${b*g} : ${c*g}.`,rat(a/gg,b/gg,c/gg),`Divide all three parts by their highest common factor.`,`HCF = ${g*gg}; ${a/gg} : ${b/gg} : ${c/gg}`)},
()=>{const [a,b]=cop(1,7),k=r(3,15);return Q(`The ratio of cats to dogs at a rescue centre is ${a} : ${b}. There are ${(a+b)*k} animals altogether (only cats and dogs). How many dogs are there?`,b*k,`Total parts = ${a+b}. Find one part, then multiply by ${b}.`,`1 part = ${(a+b)*k} ÷ ${a+b} = ${k}; dogs = ${b} × ${k} = ${b*k}`)},
()=>{const [a,b]=cop(2,9);return Q(`A map uses a ratio of 1 : ${a*10000}. Two towns are ${b} cm apart on the map. How far apart are they in real life, in km?`,b*a*10000/100000,`Multiply the map distance by ${a*10000} to get cm, then convert cm to km (÷ 100 000).`,`${b} × ${a*10000} = ${b*a*10000} cm; ÷ 100 000 = ${b*a*10000/100000} km`)}],
/* Moderate */[
()=>{const [a,b]=cop(2,7),k=r(2,9),x=r(1,4)*k;/* after adding x to first, ratio changes */const A=a*k,B=b*k;const g=gcd(A+x,B);return X(`A bag contains red and green sweets in the ratio ${a} : ${b}. There are ${A} red sweets. ${x} more red sweets are added. What is the new ratio of red to green, in its simplest form?`,rat((A+x)/g,B/g),`Use the red sweets to find one part and the number of green sweets. Then write the new ratio and simplify.`,`1 part = ${A} ÷ ${a} = ${k}; green = ${B}; new red = ${A+x}; ratio = ${A+x} : ${B} = ${(A+x)/g} : ${B/g}`)},
()=>{const [a,b]=cop(2,6),[c,d]=cop(2,6);const L=MH.lcm(b,c);const A=a*L/b,B=L,C=d*L/c;const g=gcd(gcd(A,B),C);return X(`The ratio of apples to bananas is ${a} : ${b}. The ratio of bananas to cherries is ${c} : ${d}. Find the ratio apples : bananas : cherries in its simplest form.`,rat(A/g,B/g,C/g),`Make the number of banana parts the same in both ratios (use the LCM of ${b} and ${c}).`,`LCM = ${L}; apples : bananas = ${A} : ${L}; bananas : cherries = ${L} : ${C}; ${A/g} : ${B/g} : ${C/g}`)},
()=>{const [a,b]=cop(1,5),[c,d]=cop(1,5);const P0=(a+b)*(c+d)*r(1,3);return QF(`In a group, the ratio of adults to children is ${a} : ${b}. Of the children, the ratio of boys to girls is ${c} : ${d}. What fraction of the whole group are girls? Simplest form.`,b*d,(a+b)*(c+d),`Girls are ${d}/${c+d} of the children, and children are ${b}/${a+b} of the group. Multiply the fractions.`,`${b}/${a+b} × ${d}/${c+d} = ${frac(b*d,(a+b)*(c+d))}`,{fmt:'f'})},
()=>{const [a,b]=cop(2,9),k=r(5,15);const d=Math.abs(a-b)*k;return Q(`Two angles are in the ratio ${a} : ${b}. The difference between them is ${d}°. Find the size of the larger angle (°).`,Math.max(a,b)*k,`The difference of ${Math.abs(a-b)} parts is ${d}°.`,`1 part = ${d} ÷ ${Math.abs(a-b)} = ${k}°; larger = ${Math.max(a,b)} × ${k} = ${Math.max(a,b)*k}°`)},
()=>{const [a,b]=cop(1,6),[c,d]=cop(1,6);/* a:b , total T with c:d split of the b part? use angles in triangle */const k=180/(a+b+c);if(k%1)return Q(`The angles of a triangle are in the ratio 2 : 3 : 4. Find the largest angle (°).`,80,'180 ÷ 9 = 20 per part.','4 × 20 = 80°');return Q(`The angles of a triangle are in the ratio ${a} : ${b} : ${c}. Find the largest angle (°).`,Math.max(a,b,c)*k,`The angles add to 180°. Divide 180 by the total number of parts.`,`total parts = ${a+b+c}; 1 part = ${k}°; largest = ${Math.max(a,b,c)} × ${k} = ${Math.max(a,b,c)*k}°`)}],
/* Difficult */[
()=>{const [a,b]=cop(2,6);let x,c,d;do{x=r(2,10);[c,d]=cop(2,7)}while(c*b==d*a||((x*(c-d))%(d*a-c*b))!=0||(x*(c-d))/(d*a-c*b)<=0);const k=(x*(c-d))/(d*a-c*b);const nm=who(2);/* (ak + x)/(bk + x) = c/d */return Q(`The ratio of ${nm[0]}'s age to ${nm[1]}'s age is ${a} : ${b}. In ${x} years the ratio will be ${c} : ${d}. How old is ${nm[0]} now?`,a*k,`Let the ages be ${a}k and ${b}k. In ${x} years: (${a}k + ${x}) : (${b}k + ${x}) = ${c} : ${d}. Cross-multiply and solve for k.`,`${d}(${a}k + ${x}) = ${c}(${b}k + ${x}); ${d*a}k + ${d*x} = ${c*b}k + ${c*x}; ${d*a-c*b}k = ${c*x-d*x}; k = ${k}; ${nm[0]} = ${a*k}`)},
()=>{const [a,b]=cop(2,7),k=r(4,9);const A=a*k,B=b*k;const y=r(2,k-1);const [c,d]=(()=>{const g=gcd(A-y,B+y);return[(A-y)/g,(B+y)/g]})();return Q(`Jars X and Y contain sweets in the ratio ${a} : ${b}. ${y} sweets are moved from X to Y, and the ratio becomes ${c} : ${d}. How many sweets are there altogether?`,A+B,`Let the numbers be ${a}k and ${b}k. After moving: (${a}k − ${y}) : (${b}k + ${y}) = ${c} : ${d}. The total does not change.`,`${d}(${a}k − ${y}) = ${c}(${b}k + ${y}); k = ${k}; total = ${a+b} × ${k} = ${A+B}`)},
()=>{const [a,b]=cop(1,5);const x=r(2,9);/* (x+?)/(?)... ratio with algebra: (3x+1):(x+5)=a:b */let p,q,s,t,X0;do{p=r(1,4);q=r(1,9);s=r(1,3);t=r(1,9);X0=r(1,9)}while(gcd(p*X0+q,s*X0+t)==1||(p*X0+q)==(s*X0+t));const g=gcd(p*X0+q,s*X0+t);return Q(`(${p==1?'':p}x + ${q}) : (${s==1?'':s}x + ${t}) = ${(p*X0+q)/g} : ${(s*X0+t)/g}. Find x.`,X0,`Write it as a fraction equation and cross-multiply: ${(s*X0+t)/g}(${p==1?'':p}x + ${q}) = ${(p*X0+q)/g}(${s==1?'':s}x + ${t}).`,`${(s*X0+t)/g*p}x + ${(s*X0+t)/g*q} = ${(p*X0+q)/g*s}x + ${(p*X0+q)/g*t}; x = ${X0}`)},
()=>{const [a,b]=cop(1,6),[c,d]=cop(1,6);const T=r(2,6)*(a+b)*(c+d);const A1=T*a/(a+b),B1=T*b/(a+b);/* mix A1 of mix1 (red:white c:d) ... simple: */return QF(`Paint P is blue and white in the ratio ${c} : ${d}. Paint Q is all blue. ${A1} litres of P are mixed with ${B1} litres of Q. What fraction of the mixture is blue? Simplest form.`,A1*c/(c+d)+B1,T,`Work out the litres of blue in P, add the litres of Q (all blue), then divide by the total.`,`blue in P = ${A1} × ${c}/${c+d} = ${A1*c/(c+d)}; blue total = ${A1*c/(c+d)} + ${B1} = ${A1*c/(c+d)+B1}; ÷ ${T} = ${frac(A1*c/(c+d)+B1,T)}`,{fmt:'f'})},
()=>{const [a,b]=cop(2,9);const S=r(3,9)*(a+b);return X(`A rectangle has a perimeter of ${2*S} cm. Its length and width are in the ratio ${Math.max(a,b)} : ${Math.min(a,b)}. Write length : area as a ratio of numbers (no units), in simplest form.`,(()=>{const L=Math.max(a,b)*S/(a+b),W=Math.min(a,b)*S/(a+b),A=L*W,g=gcd(L,A);return rat(L/g,A/g)})(),`Half the perimeter (${S} cm) is length + width. Share ${S} in the ratio to get the length and width, find the area, then simplify length : area.`,(()=>{const L=Math.max(a,b)*S/(a+b),W=Math.min(a,b)*S/(a+b),A=L*W,g=gcd(L,A);return `length + width = ${S}; length = ${L}; width = ${W}; area = ${A}; ${L} : ${A} = ${L/g} : ${A/g}`})())}],
/* Very Difficult */[
()=>{let a,b,k,n,c,d;do{[a,b]=cop(2,6);if(a<=b)[a,b]=[b,a];k=r(3,12);n=r(1,a*k-1);const g=gcd(a*k-n,b*k+n);c=(a*k-n)/g;d=(b*k+n)/g}while(c>12||d>12||c*b==d*a);return Q(`In a club the ratio of boys to girls is ${a} : ${b}. Then ${n} boys leave and ${n} girls join, and the ratio becomes ${c} : ${d}. How many members does the club have?`,(a+b)*k,`Let there be ${a}k boys and ${b}k girls. Form an equation from the new ratio and solve for k. The total membership does not change.`,`${d}(${a}k − ${n}) = ${c}(${b}k + ${n}); ${d*a}k − ${d*n} = ${c*b}k + ${c*n}; ${d*a-c*b}k = ${c*n+d*n}; k = ${k}; total = ${a+b} × ${k} = ${(a+b)*k}`)},
()=>{const a=r(2,5),b=r(2,5),c=r(2,5);const nm=who(3);const T=(a+b+c)*r(4,12)*10;const s=T/(a+b+c);const give=s;/* C gives half to A ... */return Q(`£${T} is shared between ${nm[0]}, ${nm[1]} and ${nm[2]} in the ratio ${a} : ${b} : ${c}. ${nm[2]} then gives half of their share to ${nm[0]}. What fraction of the £${T} does ${nm[0]} now have? Give a decimal to 3 decimal places if it is not exact.`,rd((a*s+c*s/2)/T,3),`Work out each share, make the transfer, then divide ${nm[0]}'s new amount by ${T}.`,`1 part = ${s}; ${nm[0]} = ${a*s}; ${nm[2]} = ${c*s}; half = ${c*s/2}; ${nm[0]} now ${a*s+c*s/2}; ÷ ${T} = ${rd((a*s+c*s/2)/T,3)}`,{d:frac(2*a+c,2*(a+b+c))})},
()=>{const [p,q]=cop(1,5),[s,t]=cop(1,5);if(p*t==q*s)return Q(`x : y = 2 : 3 and y : z = 4 : 5. Find x : z as a fraction x/z.`,8/15,'Combine.','x : y : z = 8 : 12 : 15',{d:'8/15'});return QF(`x : y = ${p} : ${q} and y : z = ${s} : ${t}. Find the value of x/z as a fraction in its simplest form.`,p*s,q*t,`x/z = (x/y) × (y/z).`,`x/y = ${p}/${q}; y/z = ${s}/${t}; x/z = ${frac(p*s,q*t)}`,{fmt:'f'})},
()=>{const [a,b]=cop(2,7);const w=r(2,6);/* wages ratio 'a:b'; after both get raise of w*10 ratio c:d */let k,c,d;for(let t=0;t<50;t++){k=r(3,20);const A=a*k*10,B=b*k*10,R=w*10;const g=gcd(A+R,B+R);c=(A+R)/g;d=(B+R)/g;if(c<15&&d<15)break}const nm=who(2);return Q(`${nm[0]}'s and ${nm[1]}'s weekly wages are in the ratio ${a} : ${b}. They each get a rise of £${w*10}, and the ratio becomes ${c} : ${d}. How much did ${nm[0]} get before the rise (£)?`,a*k*10,`Let the amounts be ${a}x and ${b}x. Then (${a}x + ${w*10}) : (${b}x + ${w*10}) = ${c} : ${d}. Cross-multiply.`,`${d}(${a}x + ${w*10}) = ${c}(${b}x + ${w*10}); x = ${k*10}; ${nm[0]} = ${a} × ${k*10} = ${a*k*10}`)},
()=>{const [a,b]=cop(3,9);/* concrete mix cement:sand:gravel 1:a:b by mass, total mass ... */const T=r(4,12)*(1+a+b)*10;const bag=pick([25,40]);const cem=T/(1+a+b);return Q(`Concrete is made by mixing cement, sand and gravel in the ratio 1 : ${a} : ${b} by mass. A builder needs ${T} kg of concrete. Cement is sold in ${bag} kg bags. How many bags of cement must be bought?`,Math.ceil(cem/bag),`Find the mass of cement (1 part), then divide by ${bag} and round UP — you cannot buy part of a bag.`,`total parts = ${1+a+b}; cement = ${T} ÷ ${1+a+b} = ${cem} kg; ${cem} ÷ ${bag} = ${rd(cem/bag,3)}; round up: ${Math.ceil(cem/bag)} bags`)}]]);

/* ===== Direct proportion ===== */
add('Ratio, Proportion & Rates of Change','Direct proportion',[
/* Easy */[
()=>{const n=r(3,8),c=r(12,45)*5,m=r(2,12);return Q(`${n} identical books cost £${gb(n*c/100)}. How much do ${m} of these books cost (£)?`,rd(m*c/100,2),`Direct proportion: find the cost of 1 book, then multiply.`,`1 book = £${gb(c/100)}; ${m} books = £${money(m*c/100)}`,{d:money(m*c/100)})},
()=>{const k=r(2,9),x=r(2,12),x2=r(2,15);return Q(`y is directly proportional to x. When x = ${x}, y = ${k*x}. Find y when x = ${x2}.`,k*x2,`y = kx. Find k first: k = y ÷ x.`,`k = ${k*x} ÷ ${x} = ${k}; y = ${k} × ${x2} = ${k*x2}`)},
()=>{const p=r(4,9),g=r(5,15)*10,m=r(2,12);return Q(`A recipe for ${p} people uses ${g} g of rice. How much rice is needed for ${m} people (g)?`,rd(g*m/p,2),`Find the amount for 1 person, then multiply by ${m}.`,`${g} ÷ ${p} = ${rd(g/p,3)} g per person; × ${m} = ${rd(g*m/p,2)} g`)},
()=>{const r1=pick([1.15,1.17,1.2,1.25]),eu=r(4,40)*10;return Q(`£1 = €${r1}. Change £${eu} into euros.`,rd(eu*r1,2),`Multiply pounds by ${r1}.`,`${eu} × ${r1} = ${rd(eu*r1,2)}`,{d:gb(rd(eu*r1,2))})},
()=>{const k=r(2,6);return M(`Which graph shows that y is directly proportional to x? Options: a straight line through the origin;  a straight line that does not pass through the origin;  a curve that gets closer and closer to the axes;  a horizontal line`,['a straight line through the origin','a straight line that does not pass through the origin','a curve that gets closer and closer to the axes','a horizontal line'],`Direct proportion means y = kx: a straight line through (0, 0).`)}],
/* Moderate */[
()=>{const k=r(2,5),x=r(2,6),x2=r(2,8);return Q(`y is directly proportional to x². When x = ${x}, y = ${k*x*x}. Find y when x = ${x2}.`,k*x2*x2,`y = kx². Find k using the values you are given.`,`k = ${k*x*x} ÷ ${x*x} = ${k}; y = ${k} × ${x2}² = ${k*x2*x2}`)},
()=>{const k=r(2,9);const x=r(2,8),y=k*x;const y2=k*r(2,12);return Q(`P is directly proportional to Q. P = ${y} when Q = ${x}. Find Q when P = ${y2}.`,y2/k,`P = kQ. Find k, then rearrange to find Q.`,`k = ${y} ÷ ${x} = ${k}; Q = ${y2} ÷ ${k} = ${y2/k}`)},
()=>{const k=r(2,9),x=r(2,10);const o=[`y = ${k}x`,`y = x/${k}`,`y = ${k}/x`,`y = x + ${k}`];return M(`y is directly proportional to x, and y = ${k*x} when x = ${x}. Which is the formula for y in terms of x? Options: ${shuf(o.slice()).join(';  ')}`,o,`y = kx with k = ${k*x} ÷ ${x} = ${k}.`)},
()=>{const w=r(3,9)*10,mins=r(2,9),m2=r(2,15);return Q(`A machine fills ${w} bottles in ${mins} minutes. At the same rate, how many bottles does it fill in ${m2} minutes? Give your answer to the nearest whole number.`,Math.round(w*m2/mins),`Find the number filled per minute, then multiply.`,`${w} ÷ ${mins} = ${rd(w/mins,3)} per minute; × ${m2} = ${rd(w*m2/mins,3)} ≈ ${Math.round(w*m2/mins)}`)},
()=>{const k=r(2,9);const xs=[r(1,4),r(5,8)];return Q(`The table shows values of x and y, where y is directly proportional to x. x = ${xs[0]}, y = ${k*xs[0]}; x = ${xs[1]}, y = ?. Find the missing value.`,k*xs[1],`Direct proportion: y ÷ x is constant.`,`k = ${k*xs[0]} ÷ ${xs[0]} = ${k}; y = ${k} × ${xs[1]} = ${k*xs[1]}`)}],
/* Difficult */[
()=>{const k=r(2,5),x=r(2,5);const x2=x*pick([2,3]);return Q(`y is directly proportional to x³. When x = ${x}, y = ${k*x**3}. Find y when x = ${x2}.`,k*x2**3,`y = kx³. Find k first.`,`k = ${k*x**3} ÷ ${x**3} = ${k}; y = ${k} × ${x2}³ = ${k*x2**3}`)},
()=>{const k=pick([2,3,4,5]),x=pick([4,9,16,25,36]),x2=pick([49,64,81,100,144]);return Q(`y is directly proportional to √x. When x = ${x}, y = ${k*Math.sqrt(x)}. Find y when x = ${x2}.`,k*Math.sqrt(x2),`y = k√x. Find k first.`,`√${x} = ${Math.sqrt(x)}; k = ${k*Math.sqrt(x)} ÷ ${Math.sqrt(x)} = ${k}; y = ${k} × √${x2} = ${k*Math.sqrt(x2)}`)},
()=>{const f=pick([2,3,4,5]);return Q(`y is directly proportional to x². If x is multiplied by ${f}, what is y multiplied by?`,f*f,`y = kx². Replacing x with ${f}x gives k(${f}x)² = ${f*f}kx².`,`(${f})² = ${f*f}`)},
()=>{const k=r(2,6),x=r(2,5),y2=k*r(3,8)**2;return Q(`A is directly proportional to the square of r. A = ${k*x*x} when r = ${x}. Find r when A = ${y2} (r > 0).`,Math.sqrt(y2/k),`A = kr². Find k, then rearrange and square root.`,`k = ${k*x*x} ÷ ${x*x} = ${k}; r² = ${y2} ÷ ${k} = ${y2/k}; r = ${Math.sqrt(y2/k)}`)},
()=>{const p=pick([10,20,25,50]);const inc=rd(((1+p/100)**2-1)*100,2);return Q(`y is directly proportional to x². x is increased by ${p}%. By what percentage does y increase?`,inc,`Use multipliers: x becomes ${1+p/100}x, so y becomes (${1+p/100})² times as big.`,`${1+p/100}² = ${rd((1+p/100)**2,4)}; increase = ${inc}%`)}],
/* Very Difficult */[
()=>{const k=r(2,5),d=pick([2,3]);const x=r(2,4),t=r(2,5);/* d = k t^2 ; falling object */const D1=k*t*t,t2=t+r(1,3);return Q(`The distance d metres an object falls is directly proportional to the square of the time, t seconds. It falls ${D1} m in ${t} seconds. How much FURTHER does it fall between t = ${t} and t = ${t2}?`,k*t2*t2-D1,`d = kt². Find k, then the distance at t = ${t2}, then subtract.`,`k = ${D1} ÷ ${t*t} = ${k}; d(${t2}) = ${k} × ${t2*t2} = ${k*t2*t2}; further = ${k*t2*t2} − ${D1} = ${k*t2*t2-D1}`)},
()=>{const f=pick([2,3]);const pc=rd((f**3-1)*100,0);return Q(`The mass of a solid ball is directly proportional to the cube of its radius. Ball B has a radius ${f} times that of ball A. Ball A has a mass of ${r(20,80)} g, and both are made of the same material. By what percentage is the mass of B greater than the mass of A?`,pc,`Mass ∝ r³, so multiplying r by ${f} multiplies the mass by ${f}³ = ${f**3}. Then convert to a percentage increase.`,`${f}³ = ${f**3}; increase = (${f**3} − 1) × 100% = ${pc}%`)},
()=>{const k=r(2,6);const x1=r(2,4),y1=k*x1*x1;const y2=k*r(5,9)**2;/* find x2 then ratio */const x2=Math.sqrt(y2/k);return Q(`E is directly proportional to v². When v = ${x1}, E = ${y1}. Find v when E = ${y2}, then work out E ÷ v for that value.`,rd(y2/x2,4),`E = kv². Find k, solve for v (positive), then divide.`,`k = ${k}; v² = ${y2} ÷ ${k} = ${y2/k}; v = ${x2}; E ÷ v = ${y2} ÷ ${x2} = ${rd(y2/x2,4)}`)},
()=>{const a=pick([[100,40],[60,15],[80,20],[90,10]]);const [L,t]=a;const k=t/Math.sqrt(L);const L2=pick([25,36,49,64,144,169].filter(v=>v!=L));return N(`The time T seconds for a pendulum swing is directly proportional to √L, where L cm is its length. A ${L} cm pendulum has T = ${t/10}. Find T for a ${L2} cm pendulum. Give your answer to 3 significant figures.`,sf(k*Math.sqrt(L2)/10,3),'s',`T = k√L. Find k, then substitute the new length.`,`k = ${t/10} ÷ √${L} = ${rd(k/10,5)}; T = ${rd(k/10,5)} × √${L2} = ${sf(k*Math.sqrt(L2)/10,3)} s`)},
()=>{const c=r(3,9),w=r(2,6);/* cost proportional to area of square tile of side s */const s1=r(10,30),s2=s1+r(5,20);const c1=c*s1*s1/100;return Q(`The cost of a square rug is directly proportional to its area. A rug with side ${s1} cm costs £${gb(c1)}. How much does a rug with side ${s2} cm cost (£)? Give your answer to the nearest penny.`,rd(c1*(s2/s1)**2,2),`Area is proportional to side², so cost ∝ side². Multiply the cost by (${s2}/${s1})².`,`scale factor for area = (${s2} ÷ ${s1})² = ${rd((s2/s1)**2,4)}; £${gb(c1)} × ${rd((s2/s1)**2,4)} = £${money(c1*(s2/s1)**2)}`,{d:money(c1*(s2/s1)**2)})}]]);

/* ===== Inverse proportion ===== */
add('Ratio, Proportion & Rates of Change','Inverse proportion',[
/* Easy */[
()=>{const w=r(2,8),d=r(2,10)*w,w2=pk([2,4,5,8,10].filter(v=>(w*d)%v==0&&v!=w),w*2);return Q(`${w} painters take ${d} hours to paint a house. At the same rate, how long would ${w2} painters take (hours)?`,w*d/w2,`More painters means less time (inverse proportion). Total work = ${w} × ${d} painter-hours.`,`${w} × ${d} = ${w*d}; ${w*d} ÷ ${w2} = ${w*d/w2} hours`)},
()=>{const k=r(2,12)*6,x=pick([2,3,6]),x2=pk([1,4,9,12].filter(v=>k%v==0),2);return Q(`y is inversely proportional to x. When x = ${x}, y = ${k/x}. Find y when x = ${x2}.`,k/x2,`y = k/x, so k = x × y.`,`k = ${x} × ${k/x} = ${k}; y = ${k} ÷ ${x2} = ${k/x2}`)},
()=>M(`Which graph shows y inversely proportional to x (for x > 0)? Options: a curve that gets closer and closer to both axes;  a straight line through the origin;  a ∪-shaped curve;  a straight line with a positive gradient`,['a curve that gets closer and closer to both axes','a straight line through the origin','a ∪-shaped curve','a straight line with a positive gradient'],`y = k/x: as x gets bigger y gets smaller, approaching but never reaching the axes.`),
()=>{const s=pick([40,50,60,80]),t=pick([3,4,6]),s2=pk([30,40,48,60,72,90,120].filter(v=>v!=s&&(s*t)%v==0),s*2);return Q(`A journey takes ${t} hours at ${s} km/h. How long would it take at ${s2} km/h (hours)?`,s*t/s2,`For a fixed distance, speed × time is constant (inverse proportion).`,`distance = ${s} × ${t} = ${s*t} km; ${s*t} ÷ ${s2} = ${s*t/s2} hours`)},
()=>{const p=pick([4,6,8,12]),d=pick([12,18,24,36]);const p2=pk([2,3,9,16].filter(v=>(p*d)%v==0),p*2);return Q(`A box of food feeds ${p} dogs for ${d} days. How many days would it feed ${p2} dogs?`,p*d/p2,`More dogs means fewer days: dogs × days stays the same.`,`${p} × ${d} = ${p*d} dog-days; ÷ ${p2} = ${p*d/p2} days`)}],
/* Moderate */[
()=>{const k=pick([36,72,144,100,400]),x=pk([2,3,4,6].filter(v=>k%(v*v)==0),2),x2=pk([1,2,3,5,6,10].filter(v=>k%(v*v)==0&&v!=x),1);return Q(`y is inversely proportional to x². When x = ${x}, y = ${k/(x*x)}. Find y when x = ${x2}.`,k/(x2*x2),`y = k/x², so k = y × x².`,`k = ${k/(x*x)} × ${x*x} = ${k}; y = ${k} ÷ ${x2*x2} = ${k/(x2*x2)}`)},
()=>{const k=r(2,9)*12,x=pick([2,3,4,6]);const o=[`y = ${k}/x`,`y = ${k}x`,`y = x/${k}`,`y = ${k}/x²`];return M(`y is inversely proportional to x, and y = ${k/x} when x = ${x}. Which is the formula? Options: ${shuf(o.slice()).join(';  ')}`,o,`y = k/x with k = ${k/x} × ${x} = ${k}.`)},
()=>{const k=r(2,9)*60,y=pk([4,5,6,10,12].filter(v=>k%v==0),2);return Q(`P is inversely proportional to Q. When Q = ${y}, P = ${k/y}. Find Q when P = ${k/(y*2)}.`,y*2,`P = k/Q, so k = P × Q. Then Q = k ÷ P.`,`k = ${k/y} × ${y} = ${k}; Q = ${k} ÷ ${k/(y*2)} = ${y*2}`)},
()=>{const t=pick([2,3,4,5]);return Q(`y is inversely proportional to x. If x is multiplied by ${t}, y is divided by what number?`,t,`y = k/x: multiplying x by ${t} divides y by ${t}.`,`k/(${t}x) = (k/x) ÷ ${t}`)},
()=>{const n=r(3,6),d=r(6,15),n2=n+r(1,3),dd=n*d;return Q(`${n} people can pack the parcels in ${d} hours. ${n2-n} more people join before they start. How many hours does the packing take now? Give your answer to 1 decimal place if needed.`,rd(dd/n2,1),`Total work = ${n} × ${d} person-hours; share it between ${n2} people.`,`${n} × ${d} = ${dd}; ${dd} ÷ ${n2} = ${rd(dd/n2,3)} ≈ ${rd(dd/n2,1)} hours`)}],
/* Difficult */[
()=>{const k=r(2,9)*36,x=pick([2,3,6]);return Q(`F is inversely proportional to d². F = ${k/(x*x)} when d = ${x}. Find d when F = ${k/36} (d > 0).`,6,`F = k/d². Find k = F × d², then d² = k ÷ F.`,`k = ${k/(x*x)} × ${x*x} = ${k}; d² = ${k} ÷ ${k/36} = 36; d = 6`)},
()=>{const f=pick([2,3,4,5]);return QF(`y is inversely proportional to x². x is multiplied by ${f}. What is y multiplied by? Give a fraction.`,1,f*f,`y = k/x²: replacing x with ${f}x gives k/(${f*f}x²).`,`y is multiplied by 1/${f*f}`,{fmt:'f'})},
()=>{const p=pick([20,25,50,100]);const ch=rd((1/(1+p/100)-1)*100,1);return Q(`y is inversely proportional to x. x increases by ${p}%. By what percentage does y DECREASE? Give your answer to 1 decimal place.`,-ch,`y = k/x. The new y is 1/${1+p/100} of the old one. Find the change as a percentage.`,`1 ÷ ${1+p/100} = ${rd(1/(1+p/100),4)}; decrease = ${-ch}%`)},
()=>{const k=pick([64,144,256,400,900]);const x=pk([4,16,25,36].filter(v=>k%Math.sqrt(v)==0),4),x2=pk([9,16,64,100].filter(v=>k%Math.sqrt(v)==0&&v!=x),16);return Q(`y is inversely proportional to √x. When x = ${x}, y = ${k/Math.sqrt(x)}. Find y when x = ${x2}.`,k/Math.sqrt(x2),`y = k/√x, so k = y√x.`,`k = ${k/Math.sqrt(x)} × ${Math.sqrt(x)} = ${k}; y = ${k} ÷ √${x2} = ${k/Math.sqrt(x2)}`)},
()=>{const w=r(4,8),d=r(10,20),late=r(2,5),extra=r(2,4);const work=w*d;const done=w*late;const left=work-done;const t=left/(w+extra);if(t%1)return Q(`6 workers can finish a job in 10 days. After 2 days, 2 more workers join. How many more days are needed?`,6,'Count worker-days.','60 total; 12 done; 48 left; 48 ÷ 8 = 6');return Q(`${w} workers can finish a job in ${d} days. After ${late} days, ${extra} more workers join. How many MORE days are needed to finish?`,t,`Measure the job in worker-days. Subtract what is done, then share the rest between ${w+extra} workers.`,`total = ${work}; done = ${done}; left = ${left}; ${left} ÷ ${w+extra} = ${t} days`)}],
/* Very Difficult */[
()=>{const I=pick([100,180,360,400]);const d=pick([2,3]);const d2=pick([4,5,6]);/* intensity inversely proportional to d^2 */return Q(`The brightness of a lamp is inversely proportional to the square of the distance from it. At ${d} m the brightness is ${I} units. How many units is it at ${d2} m? Give your answer to 1 decimal place.`,rd(I*d*d/(d2*d2),1),`B = k/d². Find k = B × d², then substitute the new distance.`,`k = ${I} × ${d*d} = ${I*d*d}; B = ${I*d*d} ÷ ${d2*d2} = ${rd(I*d*d/(d2*d2),3)} ≈ ${rd(I*d*d/(d2*d2),1)}`)},
()=>{const p=pick([10,20,25,50]);const ch=rd((1/(1+p/100)**2-1)*100,1);return Q(`y is inversely proportional to x². x increases by ${p}%. By what percentage does y decrease? Give your answer to 1 decimal place.`,-ch,`y = k/x². The new y = k/(${1+p/100}x)², which is 1/${rd((1+p/100)**2,4)} of the old value.`,`(${1+p/100})² = ${rd((1+p/100)**2,4)}; 1 ÷ ${rd((1+p/100)**2,4)} = ${rd(1/(1+p/100)**2,4)}; decrease = ${-ch}%`)},
()=>{const a=pick([2,3]),b=pick([4,6,8]);/* y ∝ 1/x and x ∝ z^2: y ∝ 1/z^2 */const k=pick([144,288,576]);return Q(`y is inversely proportional to x, and x is directly proportional to z². When z = ${a}, y = ${k/(a*a)}. Find y when z = ${b}.`,k/(b*b),`Combine: y = k/x and x = cz², so y = K/z² for some constant K.`,`K = ${k/(a*a)} × ${a*a} = ${k}; y = ${k} ÷ ${b*b} = ${k/(b*b)}`)},
()=>{const n=r(4,8),h=r(5,9),N=r(10,20);const hours=n*h;/* n pumps empty tank in h hours; how many pumps to empty in at most T hours */const T=r(2,h-1);const need=Math.ceil(hours/T);return Q(`${n} identical pumps can empty a flooded basement in ${h} hours. How many pumps are needed to empty it in ${T} hours or less? Each pump costs £${N*5} a day to hire.`,need,`Pump-hours stay the same: ${n} × ${h}. Divide by ${T} and round UP to a whole pump. The hire cost is not needed.`,`${n} × ${h} = ${hours} pump-hours; ${hours} ÷ ${T} = ${rd(hours/T,3)}; round up: ${need} pumps`)},
()=>{const V=pick([12,18,24,30]),P=pick([100,150,200]);const V2=pk([8,9,10,15,16,20,36].filter(v=>(V*P)%v==0&&v!=V),V*2);return Q(`At a constant temperature, the pressure P of a gas is inversely proportional to its volume V. P = ${P} kPa when V = ${V} litres. The gas is squashed until P = ${V*P/V2} kPa. What is the new volume (litres)?`,V2,`P = k/V, so PV = k is constant.`,`k = ${P} × ${V} = ${P*V}; V = ${P*V} ÷ ${V*P/V2} = ${V2}`)}]]);

/* ===== Percentages (financial) ===== */
add('Ratio, Proportion & Rates of Change','Percentages',[
/* Easy */[
()=>{const P0=r(4,40)*50,rr=pick([2,3,4,5]),n=r(2,6);return Q(`£${P0} is invested at ${rr}% simple interest per year. How much interest is earned in ${n} years (£)?`,P0*rr*n/100,`Simple interest is the same every year: ${rr}% of £${P0}, multiplied by ${n}.`,`${rr}% of ${P0} = ${P0*rr/100}; × ${n} = ${P0*rr*n/100}`)},
()=>{const p=r(4,40)*5,v=20;return Q(`A coat costs £${p} before VAT. VAT is 20%. What is the price including VAT (£)?`,p*1.2,`Add 20%: multiply by 1.2.`,`${p} × 1.2 = ${rd(p*1.2,2)}`,{d:gb(p*1.2)})},
()=>{const h=r(8,15),w=r(20,40),ot=pick([1.5,2]);const hrs=r(2,6);return Q(`A worker is paid £${h} an hour for ${w} hours a week. Overtime is paid at ${ot==1.5?'time and a half':'double time'}. How much is she paid for a week with ${w} normal hours and ${hrs} hours of overtime (£)?`,h*w+h*ot*hrs,`Overtime rate = £${h} × ${ot}. Add normal pay and overtime pay.`,`normal = ${h} × ${w} = ${h*w}; overtime rate = ${h*ot}; overtime = ${h*ot} × ${hrs} = ${h*ot*hrs}; total = ${h*w+h*ot*hrs}`)},
()=>{const c=r(5,40)*2,s=c+r(1,20);return Q(`A trader buys a lamp for £${c} and sells it for £${s}. What is the profit as a percentage of the cost price? Give your answer to 1 decimal place.`,rd((s-c)/c*100,1),`Percentage profit = profit ÷ cost price × 100.`,`profit = ${s-c}; ${s-c} ÷ ${c} × 100 = ${rd((s-c)/c*100,1)}%`)},
()=>{const b=r(5,30)*10,d=pick([10,15,20,25,30]);return Q(`A phone bill is £${b} a year. A family gets a ${d}% discount. How much do they pay (£)?`,b*(100-d)/100,`Multiply by ${(100-d)/100} (or subtract ${d}%).`,`${b} × ${(100-d)/100} = ${b*(100-d)/100}`)}],
/* Moderate */[
()=>{const a=r(2,6)*100,pa=pick([12,15,18,20]),bb=r(2,6)*100,pb=pick([8,10,12,15]);const opts=[`Offer A: £${a} off then ${pa}% off`,`Offer B`];const A=(r(10,30)*50);const v1=(A-a/10)*(1-pa/100),v2=A*(1-pb/100)-bb/10;const best=v1<v2?'A':'B';return M(`A sofa costs £${A}. Offer A: £${a/10} off, then ${pa}% off the new price. Offer B: ${pb}% off, then £${bb/10} off the new price. Which offer is cheaper? Options: Offer ${best} is cheaper;  Offer ${best=='A'?'B':'A'} is cheaper;  They give the same price;  You cannot tell`,[`Offer ${best} is cheaper`,`Offer ${best=='A'?'B':'A'} is cheaper`,'They give the same price','You cannot tell'],`Work out the final price for each offer, applying the steps in the given order. A: (${A} − ${a/10}) × ${1-pa/100} = ${money(v1)}. B: ${A} × ${1-pb/100} − ${bb/10} = ${money(v2)}.`)},
()=>{const s=r(18,45)*1000,tf=12570,rt=20;const tax=Math.max(0,s-tf)*rt/100;return Q(`A worker earns £${s.toLocaleString('en-GB')} a year. The first £12,570 is tax-free. The rest is taxed at 20%. How much tax does she pay per year (£)?`,tax,`Subtract the tax-free amount, then find 20% of what is left.`,`taxable = ${s} − 12570 = ${s-tf}; 20% = ${tax}`)},
()=>{const p=r(10,60)*10,i=pick([3,4,5]),n=r(2,8);const I=p*i*n/100;return Q(`£${p} is invested at ${i}% simple interest per year. What is the total value of the investment after ${n} years (£)?`,p+I,`Interest each year = ${i}% of £${p}. Add the total interest to the original amount.`,`${i}% of ${p} = ${p*i/100}; × ${n} = ${I}; total = ${p+I}`)},
()=>{const c=r(4,40)*10,l=pick([10,15,20,25,30]);const C=c*100,S=c*(100-l);return Q(`A car was bought for £${C} and sold for £${S}. What was the percentage loss?`,l,`Percentage loss = loss ÷ cost × 100.`,`loss = ${C-S}; ${C-S} ÷ ${C} × 100 = ${l}%`)},
()=>{const p=r(4,30)*12,v=p*1.2;return Q(`A bill of £${gb(v)} includes VAT at 20%. How much of the bill is VAT (£)?`,rd(v-p,2),`The bill is 120% of the price before VAT. Find 100% (÷ 1.2), then subtract.`,`before VAT = ${gb(v)} ÷ 1.2 = ${gb(p)}; VAT = ${gb(v)} − ${gb(p)} = ${gb(v-p)}`,{d:gb(v-p)})}],
/* Difficult */[
()=>{const P0=r(4,20)*100,rr=pick([2,3,4,5]);const I=r(2,8)*P0*rr/100;const n=I/(P0*rr/100);return Q(`£${P0} is invested at ${rr}% simple interest per year. How many years until it has earned £${I} interest?`,n,`Find the interest per year, then divide the total interest by it.`,`per year = ${P0*rr/100}; ${I} ÷ ${P0*rr/100} = ${n} years`)},
()=>{const P0=r(4,20)*100,n=r(2,6),rr=pick([2,2.5,3,4,5]);const I=P0*rr*n/100;return Q(`£${P0} earns £${I} simple interest in ${n} years. What is the yearly interest rate (%)?`,rr,`Interest per year = ${I} ÷ ${n}. Then write that as a percentage of £${P0}.`,`per year = ${rd(I/n,2)}; ${rd(I/n,2)} ÷ ${P0} × 100 = ${rr}%`)},
()=>{const c=r(5,30)*10,m=pick([40,50,60,80]),u=pick([0.8,0.75,0.7]);const sold=r(60,90),N=100;const rev=sold*c*(1+m/100)+(N-sold)*c*(1+m/100)*u;const prof=rev-N*c;return Q(`A shop buys ${N} jumpers at £${c} each. It sells ${sold} of them at a ${m}% mark-up. The rest are sold in a sale at ${Math.round((1-u)*100)}% off the marked price. Find the total profit (£).`,rd(prof,2),`Marked price = £${c} × ${1+m/100}. Work out the money from full-price sales and from sale-price sales, then subtract the total cost.`,`marked = ${rd(c*(1+m/100),2)}; full price: ${sold} × ${rd(c*(1+m/100),2)} = ${rd(sold*c*(1+m/100),2)}; sale price = ${rd(c*(1+m/100)*u,2)}; sale: ${N-sold} × ${rd(c*(1+m/100)*u,2)} = ${rd((N-sold)*c*(1+m/100)*u,2)}; cost = ${N*c}; profit = ${rd(prof,2)}`,{d:money(prof)})},
()=>{const s=r(55,75)*1000;const tf=12570,hr=50270;const tax=(Math.min(s,hr)-tf)*0.2+Math.max(0,s-hr)*0.4;return Q(`Income tax: the first £12,570 is tax-free; earnings from £12,571 to £50,270 are taxed at 20%; earnings above £50,270 are taxed at 40%. How much tax is paid on a salary of £${s.toLocaleString('en-GB')} (£)?`,rd(tax,2),`Split the salary into bands and work out the tax for each band separately.`,`20% band: (50270 − 12570) × 0.2 = 7540; 40% band: (${s} − 50270) × 0.4 = ${rd((s-hr)*0.4,2)}; total = ${rd(tax,2)}`)},
()=>{const p=pick([20,25,30,40]);const ex=rd(p/(100+p)*100,1);return Q(`A shop sells items at a ${p}% profit on the cost price. What percentage of the SELLING price is profit? Give your answer to 1 decimal place.`,ex,`Take the cost as 100. Then selling price = ${100+p} and profit = ${p}.`,`profit ÷ selling price = ${p} ÷ ${100+p}; × 100 = ${ex}%`)}],
/* Very Difficult */[
()=>{const n=who(),A=r(20,40)*100,B=r(20,40)*100,ra=pick([3,4,5]),rb=pick([2,3]),t=r(3,6);/* A simple, B compound */const sa=A*ra*t/100,cb=B*((1+rb/100)**t-1);const tot=sa+cb;return Q(`${n} puts £${A} in Account A, paying ${ra}% simple interest per year, and £${B} in Account B, paying ${rb}% compound interest per year. How much interest is earned in total after ${t} years? Give your answer to the nearest penny.`,rd(tot,2),`Simple interest: the same amount each year. Compound interest: use the multiplier ${1+rb/100} raised to the power ${t}.`,`A: ${A} × ${ra/100} × ${t} = ${rd(sa,2)}; B: ${B} × ${1+rb/100}^${t} − ${B} = ${rd(cb,2)}; total = ${money(tot)}`,{d:money(tot)})},
()=>{const m=pick([20,25,40,50]),d=pick([10,15,20,25]),vat=20;const C=r(20,80);const final=C*(1+m/100)*(1-d/100)*1.2;return Q(`A trader buys a product for £${C}. She adds a ${m}% mark-up to get the label price. In a sale the label price is reduced by ${d}%, and then VAT at 20% is added. A customer pays £${money(final)}. What percentage of what the customer pays is VAT? Give your answer to 1 decimal place.`,rd(0.2/1.2*100,1),`The customer pays 120% of the pre-VAT price, so VAT is 20/120 of what they pay, whatever the other numbers are.`,`VAT ÷ total = 20 ÷ 120 = 0.1667; = 16.7%`)},
()=>{const p=r(30,60)*10,hr=r(9,14),w=r(30,38);const bonus=pick([5,8,10]);const target=r(20,40)*10;/* commission */const sales=r(80,160)*100,cm=pick([2,3,5]);const pay=hr*w*4+sales*cm/100;return Q(`A sales assistant is paid £${hr} an hour for ${w} hours a week, plus ${cm}% commission on her sales. In a 4-week month she sells £${sales.toLocaleString('en-GB')} of goods. What is her total pay for the month (£)?`,pay,`Hourly pay: £${hr} × ${w} × 4. Commission: ${cm}% of £${sales}. Add them.`,`hourly = ${hr} × ${w} × 4 = ${hr*w*4}; commission = ${sales} × ${cm/100} = ${sales*cm/100}; total = ${pay}`)},
()=>{const a=pick([20,25,50]),b=pick([20,25,40]);/* price up a%, then sales down b%: change in revenue */const ch=rd(((1+a/100)*(1-b/100)-1)*100,1);return Q(`A cinema increases its ticket price by ${a}%. As a result, the number of tickets sold falls by ${b}%. What is the percentage change in the cinema's ticket income? (Give a negative answer for a decrease.)`,ch,`Income = price × number sold. Multiply the two multipliers.`,`${1+a/100} × ${1-b/100} = ${rd((1+a/100)*(1-b/100),4)}; change = ${ch}%`)},
()=>{const P0=r(10,40)*100,rr=pick([4,5,6]),n=r(2,4);/* simple interest equal to compound? ask difference */const simple=P0*rr*n/100,comp=P0*((1+rr/100)**n-1);return Q(`£${P0} is invested for ${n} years at ${rr}% per year. How much MORE interest is earned with compound interest than with simple interest? Give your answer to the nearest penny.`,rd(comp-simple,2),`Simple: ${rr}% of the original each year. Compound: multiply by ${1+rr/100} each year. Subtract the two amounts of interest.`,`simple = ${rd(simple,2)}; compound = ${P0} × ${1+rr/100}^${n} − ${P0} = ${rd(comp,2)}; difference = ${money(comp-simple)}`,{d:money(comp-simple)})}]]);

/* ===== Compound interest ===== */
add('Ratio, Proportion & Rates of Change','Compound interest',[
/* Easy */[
()=>{const P0=r(2,20)*100,rr=pick([2,3,4,5,10]);return Q(`£${P0} is invested at ${rr}% compound interest per year. What is it worth after 2 years (£)?`,rd(P0*(1+rr/100)**2,2),`Multiply by ${1+rr/100} once for each year.`,`year 1: ${P0} × ${1+rr/100} = ${rd(P0*(1+rr/100),2)}; year 2: × ${1+rr/100} = ${money(P0*(1+rr/100)**2)}`,{d:money(P0*(1+rr/100)**2)})},
()=>{const rr=pick([2,3,4,5,6,8,12,15]);return Q(`What is the multiplier for an increase of ${rr}%?`,1+rr/100,`100% + ${rr}% = ${100+rr}% = ${1+rr/100}.`,`${1+rr/100}`)},
()=>{const P0=r(2,20)*100,rr=pick([10,20]);return Q(`£${P0} is invested at ${rr}% compound interest per year. How much interest is earned in 2 years (£)?`,rd(P0*((1+rr/100)**2-1),2),`Find the value after 2 years, then subtract the original amount.`,`${P0} × ${1+rr/100}² = ${rd(P0*(1+rr/100)**2,2)}; interest = ${rd(P0*((1+rr/100)**2-1),2)}`)},
()=>{const P0=r(5,20)*100,rr=pick([2,3,5]),n=r(3,5);return Q(`£${P0} is invested at ${rr}% compound interest per year for ${n} years. What is its final value (£)? Give your answer to the nearest penny.`,rd(P0*(1+rr/100)**n,2),`Final value = ${P0} × ${1+rr/100}<sup>${n}</sup>.`,`${1+rr/100}^${n} = ${rd((1+rr/100)**n,6)}; × ${P0} = ${money(P0*(1+rr/100)**n)}`,{d:money(P0*(1+rr/100)**n)})},
()=>{const rr=pick([5,10,15,20]);return Q(`What is the multiplier for a DECREASE of ${rr}%?`,1-rr/100,`100% − ${rr}% = ${100-rr}% = ${1-rr/100}.`,`${1-rr/100}`)}],
/* Moderate */[
()=>{const P0=r(10,50)*100,rr=pick([1.5,2.5,3.5,4.2]),n=r(3,8);return Q(`£${P0} is invested at ${rr}% compound interest per year. What is it worth after ${n} years? Give your answer to the nearest penny.`,rd(P0*(1+rr/100)**n,2),`Use value = ${P0} × ${rd(1+rr/100,4)}<sup>${n}</sup>.`,`${rd(1+rr/100,4)}^${n} = ${rd((1+rr/100)**n,6)}; × ${P0} = ${money(P0*(1+rr/100)**n)}`,{d:money(P0*(1+rr/100)**n)})},
()=>{const P0=r(10,50)*100,rr=pick([2,3,4,5]),n=r(3,6);const I=P0*((1+rr/100)**n-1);return Q(`£${P0} is saved at ${rr}% compound interest per year. How much INTEREST is earned in ${n} years? Give your answer to the nearest penny.`,rd(I,2),`Work out the final value, then subtract £${P0}.`,`final = ${P0} × ${1+rr/100}^${n} = ${rd(P0*(1+rr/100)**n,2)}; interest = ${money(I)}`,{d:money(I)})},
()=>{const P0=r(2,10)*1000,rr=pick([3,4,5,6]),T=P0*pick([1.2,1.25,1.3]);let n=0,v=P0;while(v<T){v*=1+rr/100;n++}return Q(`£${P0} is invested at ${rr}% compound interest per year. After how many whole years will it first be worth more than £${T}?`,n,`Keep multiplying by ${1+rr/100}, year by year, until the value passes £${T}.`,`after ${n-1} years: ${money(P0*(1+rr/100)**(n-1))}; after ${n} years: ${money(P0*(1+rr/100)**n)}; answer ${n} years`)},
()=>{const rr=pick([2,3,4,5]),n=r(2,4),F=r(10,40)*100;const P0=F/(1+rr/100)**n;return Q(`An investment earns ${rr}% compound interest per year. After ${n} years it is worth £${F}. How much was invested at the start? Give your answer to the nearest penny.`,rd(P0,2),`Work backwards: divide by ${1+rr/100}<sup>${n}</sup>.`,`${1+rr/100}^${n} = ${rd((1+rr/100)**n,6)}; ${F} ÷ ${rd((1+rr/100)**n,6)} = ${money(P0)}`,{d:money(P0)})},
()=>{const P0=r(5,20)*100,rr=pick([2,3,4]),n=r(3,6);const cmp=P0*(1+rr/100)**n,sim=P0*(1+rr*n/100);return M(`£${P0} is invested for ${n} years at ${rr}% per year. Which statement is true? Options: compound interest gives more;  simple interest gives more;  they give the same;  it depends on the bank`,['compound interest gives more','simple interest gives more','they give the same','it depends on the bank'],`Compound interest earns interest on the interest. Compound: £${money(cmp)}; simple: £${money(sim)}.`)}],
/* Difficult */[
()=>{const P0=r(10,40)*100,rr=pick([2,3,4]),n=r(3,6);const F=P0*(1+rr/100)**n;return Q(`£${P0} grows to £${money(F)} after ${n} years of compound interest. What is the yearly interest rate (%)?`,rr,`Write ${money(F)} = ${P0} × m<sup>${n}</sup>. Find m by taking the ${n}th root of ${money(F)} ÷ ${P0}.`,`${money(F)} ÷ ${P0} = ${rd(F/P0,6)}; ${n}th root = ${rd((F/P0)**(1/n),4)}; rate = ${rr}%`)},
()=>{const P0=r(10,50)*100,r1=pick([2,3,4]),r2=pick([5,6]),n1=r(2,3),n2=r(2,3);const F=P0*(1+r1/100)**n1*(1+r2/100)**n2;return Q(`£${P0} is invested at ${r1}% compound interest for ${n1} years, then the rate changes to ${r2}% for another ${n2} years. Find the final value, to the nearest penny.`,rd(F,2),`Apply each multiplier for the right number of years: ${P0} × ${1+r1/100}<sup>${n1}</sup> × ${1+r2/100}<sup>${n2}</sup>.`,`${P0} × ${rd((1+r1/100)**n1,6)} × ${rd((1+r2/100)**n2,6)} = ${money(F)}`,{d:money(F)})},
()=>{const P0=r(10,40)*100,rr=pick([3,4,5]);const m=rd((1+rr/100)/1,4);/* monthly vs yearly? Use half-yearly */const n=r(2,4);const F=P0*(1+rr/200)**(2*n);return Q(`£${P0} is invested at ${rr}% per year, compounded every 6 months (so ${rr/2}% is added each half-year). What is it worth after ${n} years? Give your answer to the nearest penny.`,rd(F,2),`There are ${2*n} half-years. Multiply by ${1+rr/200} for each one.`,`${P0} × ${1+rr/200}^${2*n} = ${money(F)}`,{d:money(F)})},
()=>{const rr=pick([5,6,8,10]);let n=0,v=1;while(v<2){v*=1+rr/100;n++}return Q(`Money is invested at ${rr}% compound interest per year. After how many whole years will it first be more than double its original value?`,n,`The starting amount does not matter. Find the smallest n so that ${1+rr/100}<sup>n</sup> > 2.`,`${1+rr/100}^${n-1} = ${rd((1+rr/100)**(n-1),4)}; ${1+rr/100}^${n} = ${rd((1+rr/100)**n,4)}; n = ${n}`)},
()=>{const A=r(10,30)*100,ra=pick([3,4]),B=A+r(1,5)*100,rb=pk([2,3].filter(x=>x<ra),2),n=r(3,8);const fa=A*(1+ra/100)**n,fb=B*(1+rb/100)**n;const more=fa>fb?'A':'B';return M(`Account A: £${A} at ${ra}% compound interest. Account B: £${B} at ${rb}% compound interest. Which is worth more after ${n} years? Options: Account ${more};  Account ${more=='A'?'B':'A'};  They are equal;  Not enough information`,[`Account ${more}`,`Account ${more=='A'?'B':'A'}`,'They are equal','Not enough information'],`Work out both: A = ${A} × ${1+ra/100}^${n} = £${money(fa)}; B = ${B} × ${1+rb/100}^${n} = £${money(fb)}.`)}],
/* Very Difficult */[
()=>{const rr=pick([3,4,5,6]),P0=r(10,30)*100,W=r(1,4)*100;/* each year: add interest then withdraw W */let v=P0;const steps=[];for(let i=0;i<3;i++){v=v*(1+rr/100)-W;steps.push(rd(v,2))}return Q(`£${P0} is invested at ${rr}% compound interest. At the end of each year, after the interest is added, £${W} is taken out. How much is left after 3 years? Give your answer to the nearest penny.`,rd(v,2),`Do it year by year: multiply by ${1+rr/100}, then subtract ${W}. You cannot use a single power because of the withdrawals.`,`year 1: ${steps[0]}; year 2: ${steps[1]}; year 3: ${money(v)}`,{d:money(v)})},
()=>{const rr=pick([2,3,4,5]),n=r(5,10);const pc=rd(((1+rr/100)**n-1)*100,1);return Q(`An investment grows at ${rr}% compound interest per year. By what percentage has it grown in total after ${n} years? Give your answer to 1 decimal place.`,pc,`The total multiplier is ${1+rr/100}<sup>${n}</sup>. Subtract 1 and turn into a percentage.`,`${1+rr/100}^${n} = ${rd((1+rr/100)**n,5)}; growth = ${pc}%`)},
()=>{const P0=r(10,30)*1000,rr=pick([2,3,4]),add2=r(5,20)*100,n=3;let v=P0;for(let i=0;i<n;i++){v=(v+add2)*(1+rr/100)}const steps=[];let u=P0;for(let i=0;i<n;i++){u=(u+add2)*(1+rr/100);steps.push(money(u))}return Q(`${who()} has £${P0} in savings. At the START of each year she adds £${add2}, and the account pays ${rr}% compound interest at the end of each year. How much is in the account after ${n} years? Give your answer to the nearest penny.`,rd(v,2),`Work year by year: add £${add2}, then multiply by ${1+rr/100}.`,`year 1: ${steps[0]}; year 2: ${steps[1]}; year 3: ${steps[2]}`,{d:money(v)})},
()=>{const ra=pick([4,5]),rb=pick([3,3.5]),A=r(10,30)*100;let n=1;/* A at ra compound vs B simple at higher rate */const rs=ra+pick([1,2]);while(A*(1+ra/100)**n<=A*(1+rs*n/100))n++;return Q(`£${A} can be invested with simple interest at ${rs}% per year, or with compound interest at ${ra}% per year. After how many whole years does the compound option first give MORE money?`,n,`Compare A × ${1+ra/100}<sup>n</sup> with A × (1 + ${rs/100}n) for n = 1, 2, 3, … The starting amount cancels.`,`n = ${n-1}: ${rd((1+ra/100)**(n-1),4)} vs ${rd(1+rs*(n-1)/100,4)}; n = ${n}: ${rd((1+ra/100)**n,4)} vs ${rd(1+rs*n/100,4)}; first year = ${n}`)},
()=>{const F=r(20,60)*100,rr=pick([3,4,5]),n=r(3,6);const P0=F/(1+rr/100)**n;const I=F-P0;return Q(`After ${n} years of ${rr}% compound interest, an account holds £${F}. How much of this is interest? Give your answer to the nearest penny.`,rd(I,2),`First find the original amount by dividing by ${1+rr/100}<sup>${n}</sup>. The interest is the difference.`,`original = ${F} ÷ ${rd((1+rr/100)**n,6)} = ${money(P0)}; interest = ${money(I)}`,{d:money(I)})}]]);

/* ===== Growth and decay ===== */
add('Ratio, Proportion & Rates of Change','Growth and decay',[
/* Easy */[
()=>{const v=r(10,40)*1000,d=pick([10,15,20,25]);return Q(`A car worth £${v} loses ${d}% of its value each year. What is it worth after 1 year (£)?`,v*(1-d/100),`Multiply by ${1-d/100}.`,`${v} × ${1-d/100} = ${v*(1-d/100)}`)},
()=>{const p=r(2,9)*100,g=pick([10,20,50]);return Q(`A colony of ${p} bacteria grows by ${g}% each hour. How many are there after 2 hours?`,Math.round(p*(1+g/100)**2),`Multiply by ${1+g/100} each hour.`,`${p} × ${1+g/100} = ${p*(1+g/100)}; × ${1+g/100} = ${rd(p*(1+g/100)**2,2)}`)},
()=>{const d=pick([5,10,15,20,25,30]);return Q(`A value decreases by ${d}% each year. What single number do you multiply by for each year?`,1-d/100,`100% − ${d}% = ${100-d}%.`,`${1-d/100}`)},
()=>{const m=r(2,10)*40,h=pick([2,3]);return Q(`A radioactive sample has a mass of ${m} g. Its half-life is 1 day (it halves every day). What mass is left after ${h} days (g)?`,m/2**h,`Halve the mass once for each day.`,`${Array.from({length:h+1},(_,i)=>m/2**i).join(' → ')}`)},
()=>{const v=r(10,40)*100,g=pick([2,5,10]);return M(`The population of a town is ${v} and grows by ${g}% each year. Which calculation gives the population after 3 years? Options: ${v} × ${1+g/100}³;  ${v} × ${1+3*g/100};  ${v} + 3 × ${g};  ${v} × ${g/100}³`,[`${v} × ${1+g/100}³`,`${v} × ${1+3*g/100}`,`${v} + 3 × ${g}`,`${v} × ${g/100}³`],`Repeated percentage growth: multiply by ${1+g/100} three times.`)}],
/* Moderate */[
()=>{const v=r(10,40)*1000,d=pick([8,12,15,18]),n=r(3,6);return Q(`A van bought for £${v} depreciates by ${d}% per year. What is it worth after ${n} years? Give your answer to the nearest pound.`,Math.round(v*(1-d/100)**n),`Value = ${v} × ${1-d/100}<sup>${n}</sup>.`,`${1-d/100}^${n} = ${rd((1-d/100)**n,6)}; × ${v} = ${rd(v*(1-d/100)**n,2)} ≈ ${Math.round(v*(1-d/100)**n)}`)},
()=>{const p=r(2,9)*1000,g=pick([3,4,5,6]),n=r(4,10);return Q(`A town has ${p} people and grows by ${g}% per year. Estimate its population after ${n} years, to the nearest whole number.`,Math.round(p*(1+g/100)**n),`Population = ${p} × ${1+g/100}<sup>${n}</sup>.`,`${1+g/100}^${n} = ${rd((1+g/100)**n,6)}; × ${p} = ${rd(p*(1+g/100)**n,2)}`)},
()=>{const v=r(10,40)*1000,d=pick([10,15,20,25]);let n=0,x=v;const T=v/2;while(x>T){x*=1-d/100;n++}return Q(`A machine worth £${v} loses ${d}% of its value each year. After how many whole years is it first worth less than half its original value?`,n,`Multiply by ${1-d/100} year by year until the value drops below £${v/2}.`,`after ${n-1} years: ${Math.round(v*(1-d/100)**(n-1))}; after ${n} years: ${Math.round(v*(1-d/100)**n)}; answer ${n}`)},
()=>{const m=r(2,8)*100,hl=pick([2,3,5,8]),k=pick([2,3,4]);return Q(`A substance has a half-life of ${hl} hours. A sample has a mass of ${m} mg. What mass remains after ${hl*k} hours (mg)?`,m/2**k,`${hl*k} hours is ${k} half-lives. Halve ${k} times.`,`${hl*k} ÷ ${hl} = ${k} half-lives; ${m} ÷ 2^${k} = ${m/2**k}`)},
()=>{const v=r(10,40)*100,g=pick([10,20,25]),n=2;const F=v*(1+g/100)**n;return Q(`A collection of stamps is worth £${money(F)} now. Its value has increased by ${g}% each year for the last ${n} years. What was it worth ${n} years ago (£)?`,v,`Work backwards: divide by ${1+g/100} twice (or by ${1+g/100}²).`,`${money(F)} ÷ ${rd((1+g/100)**2,4)} = ${v}`)}],
/* Difficult */[
()=>{const v=r(10,40)*1000,d=pick([10,15,20]),n=r(2,4);const F=v*(1-d/100)**n;return Q(`After ${n} years of depreciating by the same percentage each year, a car worth £${v} is now worth £${money(F)}. What is the yearly rate of depreciation (%)?`,d,`F = V × m<sup>${n}</sup>. Find m = (F ÷ V)<sup>1/${n}</sup>, then the rate is 1 − m.`,`${money(F)} ÷ ${v} = ${rd(F/v,6)}; ${n}th root = ${rd((F/v)**(1/n),4)}; rate = ${d}%`)},
()=>{const p=r(2,9)*100,g=pick([5,8,10,12]);let n=0,x=p;while(x<2*p){x*=1+g/100;n++}return Q(`A population of ${p} animals grows by ${g}% per year. After how many whole years will it first have doubled?`,n,`Find the smallest n with ${1+g/100}<sup>n</sup> ≥ 2.`,`${1+g/100}^${n-1} = ${rd((1+g/100)**(n-1),4)}; ${1+g/100}^${n} = ${rd((1+g/100)**n,4)}; n = ${n}`)},
()=>{const m=r(2,9)*100,k=pick([0.9,0.8,0.85]);const u=[m];for(let i=0;i<3;i++)u.push(rd(u[i]*k,4));return Q(`The iteration formula u<sub>n+1</sub> = ${k}u<sub>n</sub> models a cooling drink, with u<sub>0</sub> = ${m}. Find u<sub>3</sub>. Give your answer to 1 decimal place.`,rd(u[3],1),`Apply the formula three times, starting from u<sub>0</sub> = ${m}.`,`u1 = ${u[1]}; u2 = ${u[2]}; u3 = ${rd(u[3],4)}`)},
()=>{const a=pick([10,20]),b=pick([10,15]);const ch=rd(((1+a/100)*(1-b/100)**2-1)*100,2);return Q(`A share price rises by ${a}% in year 1, then falls by ${b}% in each of years 2 and 3. What is the overall percentage change? (Give a negative answer for a fall.) Give 2 decimal places.`,ch,`Multiply all the multipliers: ${1+a/100} × ${1-b/100} × ${1-b/100}.`,`${1+a/100} × ${1-b/100}² = ${rd((1+a/100)*(1-b/100)**2,6)}; change = ${ch}%`)},
()=>{const v=r(10,40)*1000,d=pick([10,20]),n=r(3,5);return M(`A car loses ${d}% of its value each year. A student says "after ${n} years it has lost ${d*n}% of its value". Which is correct? Options: the loss is less than ${d*n}%, because each year's ${d}% is taken from a smaller value;  ${d*n}% is exactly right;  the loss is more than ${d*n}%;  you need the original price to decide`,[`the loss is less than ${d*n}%, because each year's ${d}% is taken from a smaller value`,`${d*n}% is exactly right`,`the loss is more than ${d*n}%`,'you need the original price to decide'],`Depreciation compounds: the multiplier is ${1-d/100}<sup>${n}</sup> = ${rd((1-d/100)**n,4)}, a loss of ${rd((1-(1-d/100)**n)*100,1)}%.`)}],
/* Very Difficult */[
()=>{const m0=r(4,9)*100,hl=pick([3,4,6]);let t=0,m=m0;while(m>=m0/10){m/=2;t+=hl}return Q(`A sample of ${m0} mg has a half-life of ${hl} days. After how many days does the mass first fall below one tenth of the starting mass? (Give a whole number of half-lives in days.)`,t,`Keep halving until the mass is below ${m0/10} mg, counting ${hl} days per half-life.`,`${m0} → ${m0/2} → ${m0/4} → ${m0/8} → ${m0/16}; below ${m0/10} after ${t/hl} half-lives = ${t} days`)},
()=>{const P0=r(2,6)*1000,g=pick([2,3]),k=r(2,4)*100;/* u_{n+1} = 1.0g u_n - k (fishing) */let u=P0;const s=[];for(let i=0;i<3;i++){u=u*(1+g/100)-k;s.push(rd(u,2))}return Q(`A lake has ${P0} fish. Each year the number grows by ${g}%, and then ${k} fish are caught. How many fish are there after 3 years? Give your answer to the nearest whole number.`,Math.round(u),`Work year by year: multiply by ${1+g/100}, then subtract ${k}.`,`year 1: ${s[0]}; year 2: ${s[1]}; year 3: ${s[2]}; ≈ ${Math.round(u)}`)},
()=>{const v=r(10,40)*1000,d1=pick([20,25]),d2=pick([10,15]);const n=r(3,5);const F=v*(1-d1/100)*(1-d2/100)**(n-1);return Q(`A new car costs £${v}. It loses ${d1}% of its value in the first year and ${d2}% of its value in each year after that. What is it worth after ${n} years? Give your answer to the nearest pound.`,Math.round(F),`Use ${1-d1/100} once, then ${1-d2/100} for each of the remaining ${n-1} years.`,`${v} × ${1-d1/100} × ${1-d2/100}^${n-1} = ${rd(F,2)} ≈ ${Math.round(F)}`)},
()=>{const a=pick([2,3]),p=r(2,6)*100;/* population doubles every a years -> after t years find */const t=a*r(3,5);return Q(`A population of ${p} doubles every ${a} years. What will it be after ${t} years? What is the yearly growth rate, to 1 decimal place (%)? Give the growth rate only.`,rd((2**(1/a)-1)*100,1),`Doubling every ${a} years means the yearly multiplier m satisfies m<sup>${a}</sup> = 2, so m = 2<sup>1/${a}</sup>.`,`m = 2^(1/${a}) = ${rd(2**(1/a),4)}; rate = ${rd((2**(1/a)-1)*100,1)}%`)},
()=>{const v=r(10,30)*1000,d=pick([10,15,20]),n=r(3,5);const lost=v-v*(1-d/100)**n;return Q(`A boat bought for £${v} depreciates by ${d}% each year. How much value (in £) does it LOSE in total over ${n} years? Give your answer to the nearest pound.`,Math.round(lost),`Find the value after ${n} years with the multiplier, then subtract from £${v}.`,`value = ${v} × ${1-d/100}^${n} = ${rd(v*(1-d/100)**n,2)}; lost = ${rd(lost,2)} ≈ ${Math.round(lost)}`)}]]);

/* ===== Rates of change ===== */
add('Ratio, Proportion & Rates of Change','Rates of change',[
/* Easy */[
()=>{const L=r(20,90),t=pick([2,4,5,10]);return Q(`A tap fills a ${L*t}-litre tank in ${t} minutes. What is the rate of flow in litres per minute?`,L,`Rate = amount ÷ time.`,`${L*t} ÷ ${t} = ${L}`)},
()=>{const m=r(2,9),c=r(0,20);return Q(`The graph shows the depth of water in a tank, d cm, against time, t minutes: d = ${m}t + ${c}. At what rate is the depth increasing (cm per minute)?${svgG({x0:0,x1:10,y0:0,y1:m*10+c+5,step:m*10+c>50?10:5,lab:m*10+c>50?10:5,fns:[t=>m*t+c],xl:'t',yl:'d'}).replace(/x0:0/,'')}`,m,`The rate of change is the gradient of the line.`,`gradient = ${m} cm per minute`)},
()=>{const p=r(5,15)*10,h=r(3,8);return Q(`A printer prints ${p*h} pages in ${h} minutes. How many pages per minute is that?`,p,`Divide the number of pages by the number of minutes.`,`${p*h} ÷ ${h} = ${p}`)},
()=>{const g=r(2,6);return M(`On a distance–time graph, what does the gradient represent? Options: speed;  distance;  time;  acceleration`,['speed','distance','time','acceleration'],`Gradient = change in distance ÷ change in time = speed.`)},
()=>{const w=r(30,60),d=r(2,6);return Q(`A plant grows ${w*d} mm in ${d} weeks at a steady rate. How many mm does it grow per week?`,w,`Rate = change ÷ time.`,`${w*d} ÷ ${d} = ${w}`)}],
/* Moderate */[
()=>{const t1=r(0,3),t2=t1+r(2,5),f=t=>t*t+2;return Q(`The height of a balloon is h = t² + 2 metres after t seconds. Find the AVERAGE rate of change of height between t = ${t1} and t = ${t2} (m/s).`,(f(t2)-f(t1))/(t2-t1),`Average rate = change in h ÷ change in t (the gradient of the chord).`,`h(${t1}) = ${f(t1)}; h(${t2}) = ${f(t2)}; (${f(t2)} − ${f(t1)}) ÷ (${t2} − ${t1}) = ${(f(t2)-f(t1))/(t2-t1)}`)},
()=>{const v=r(2,8),t=r(3,10);return M(`On a velocity–time graph, what does the gradient represent? Options: acceleration;  distance travelled;  speed;  time taken`,['acceleration','distance travelled','speed','time taken'],`Gradient = change in velocity ÷ change in time = acceleration. (The AREA under the graph is distance.)`)},
()=>{const a=r(2,6),T=r(3,8);return Q(`A car accelerates steadily from rest to ${a*T} m/s in ${T} seconds. What is its acceleration (m/s²)?`,a,`Acceleration = change in velocity ÷ time.`,`${a*T} ÷ ${T} = ${a}`)},
()=>{const r1=r(3,9),r2=r(3,9),t1=r(2,5),t2=r(2,5);return Q(`A tank is filled at ${r1} litres per minute for ${t1} minutes, then at ${r2} litres per minute for ${t2} minutes. What was the average rate of filling over the whole time (litres per minute)? Give 2 decimal places if needed.`,rd((r1*t1+r2*t2)/(t1+t2),2),`Average rate = total volume ÷ total time (NOT the mean of the two rates).`,`volume = ${r1*t1} + ${r2*t2} = ${r1*t1+r2*t2}; time = ${t1+t2}; rate = ${rd((r1*t1+r2*t2)/(t1+t2),2)}`)},
()=>{const p=r(12,40),s=r(2,6);return Q(`A water butt leaks at ${s} litres per hour. It starts with ${p*s} litres. How long until it is empty (hours)?`,p,`Time = amount ÷ rate.`,`${p*s} ÷ ${s} = ${p} hours`)}],
/* Difficult */[
()=>{const a=pick([1,2]),x0=r(1,4);const grad=2*a*x0;return Q(`The curve y = ${a==1?'':a}x² is drawn. A tangent is drawn at x = ${x0}. Estimate the gradient of the curve at that point. (The tangent passes through (${x0}, ${a*x0*x0}) and (${x0+1}, ${a*x0*x0+grad}).)${svgG({x0:-1,x1:6,y0:-2,y1:Math.max(20,a*x0*x0+grad+4),step:2,lab:2,fns:[x=>a*x*x,x=>a*x0*x0+grad*(x-x0)],pts:[[x0,a*x0*x0]]})}`,grad,`The gradient of a curve at a point is the gradient of the tangent there: rise ÷ run using two points on the tangent.`,`rise = ${a*x0*x0+grad} − ${a*x0*x0} = ${grad}; run = 1; gradient = ${grad}`)},
()=>{const u=r(0,5),v=u+r(5,15),T=r(4,10);return Q(`A cyclist speeds up steadily from ${u} m/s to ${v} m/s in ${T} seconds. How far does she travel in that time (m)? (Area under a velocity–time graph.)`,(u+v)/2*T,`The area under a velocity–time graph is the distance. Here it is a trapezium: ½(u + v) × T.`,`½ × (${u} + ${v}) × ${T} = ${(u+v)/2*T}`)},
()=>{const t1=r(1,3),t2=t1+r(1,3),f=t=>40-4*t*t;return Q(`The temperature of a cooling drink is T = 40 − 4t² °C after t minutes (for small t). Find the average rate of change of temperature between t = ${t1} and t = ${t2}, in °C per minute. (Give a negative answer for cooling.)`,(f(t2)-f(t1))/(t2-t1),`Average rate = change in T ÷ change in t.`,`T(${t1}) = ${f(t1)}; T(${t2}) = ${f(t2)}; (${f(t2)} − ${f(t1)}) ÷ ${t2-t1} = ${(f(t2)-f(t1))/(t2-t1)}`)},
()=>{const a=r(1,3),T1=r(2,5),c=r(2,6),T2=r(2,4);const v=a*T1;const dist=0.5*v*T1+v*c+0.5*v*T2;return Q(`A train accelerates from rest at ${a} m/s² for ${T1} s, travels at a constant speed for ${c} s, then slows steadily to rest in ${T2} s. What total distance does it travel (m)?`,dist,`Sketch the velocity–time graph: a trapezium. Top speed = ${a} × ${T1} = ${v} m/s. Distance = area under the graph.`,`speeding up: ½ × ${T1} × ${v} = ${0.5*v*T1}; steady: ${c} × ${v} = ${v*c}; slowing: ½ × ${T2} × ${v} = ${0.5*v*T2}; total = ${dist}`)},
()=>{const p=r(2,6);return M(`On a graph, a line that gets STEEPER from left to right shows that the rate of change is… Options: increasing;  decreasing;  constant;  zero`,['increasing','decreasing','constant','zero'],`Steepness is the gradient, which is the rate of change.`)}],
/* Very Difficult */[
()=>{const v=r(10,24),T=r(10,30),slow=r(4,10);/* area under v-t: accelerate T1 */const t1=r(4,8);const tot=0.5*t1*v+v*T+0.5*slow*v;return Q(`A car starts from rest and accelerates steadily to ${v} m/s in ${t1} s. It then travels at ${v} m/s for ${T} s, then decelerates steadily to rest in ${slow} s. Find the average speed for the whole journey, to 1 decimal place (m/s).`,rd(tot/(t1+T+slow),1),`Distance = area under the velocity–time graph. Average speed = total distance ÷ total time.`,`distance = ½ × ${t1} × ${v} + ${v} × ${T} + ½ × ${slow} × ${v} = ${tot}; time = ${t1+T+slow}; average = ${rd(tot/(t1+T+slow),1)} m/s`)},
()=>{const a=r(1,2),b=r(1,4),t=r(1,4);/* d = a t^3 + b t; speed at t via tangent ~ 3a t^2 + b */return Q(`The distance travelled by a toy car is d = ${a==1?'':a}t² + ${b==1?'':b}t metres after t seconds. A tangent drawn at t = ${t} has gradient ${2*a*t+b}. What does this gradient tell you, and what is its value? Give the value in m/s.`,2*a*t+b,`The gradient of a distance–time graph is the speed. The gradient of the tangent gives the speed at that instant.`,`instantaneous speed at t = ${t} is ${2*a*t+b} m/s`)},
()=>{const L=r(200,500),w=r(8,20),h=r(1,2);const rate=r(15,60)*10;const vol=L*w*h*1000/1000;/* pool fill time in hours */const time=L*w*h*1000/rate/60;return Q(`A swimming pool is a cuboid ${L/10} m long, ${w} m wide and ${h} m deep. It is filled at ${rate} litres per minute (1 m³ = 1000 litres). How many HOURS does it take to fill? Give your answer to the nearest hour.`,Math.round(L/10*w*h*1000/rate/60),`Volume in m³, then litres, then minutes (÷ rate), then hours (÷ 60).`,`volume = ${L/10} × ${w} × ${h} = ${rd(L/10*w*h,2)} m³ = ${rd(L/10*w*h*1000,0)} litres; ÷ ${rate} = ${rd(L/10*w*h*1000/rate,1)} min; ÷ 60 = ${rd(L/10*w*h*1000/rate/60,2)} h ≈ ${Math.round(L/10*w*h*1000/rate/60)}`)},
()=>{const vs=[0,r(4,8),r(9,14),r(9,14),0];const ts=[0,4,8,12,16];let area=0;for(let i=0;i<4;i++)area+=0.5*(vs[i]+vs[i+1])*4;return Q(`A runner's speed is recorded every 4 seconds: ${ts.map((t,i)=>`t = ${t}: ${vs[i]} m/s`).join(', ')}. Use 4 trapeziums to estimate the distance run in the 16 seconds (m).`,area,`Distance is the area under the velocity–time graph. Each strip is a trapezium of width 4: ½ × (v₁ + v₂) × 4.`,`${[0,1,2,3].map(i=>`½(${vs[i]} + ${vs[i+1]}) × 4 = ${0.5*(vs[i]+vs[i+1])*4}`).join('; ')}; total = ${area}`)},
()=>{const x1=r(1,3),f=x=>x*x*x;const h=0.1;const est=rd((f(x1+h)-f(x1-h))/(2*h),2);return Q(`For y = x³, estimate the gradient of the curve at x = ${x1} using the chord from x = ${rd(x1-h,1)} to x = ${rd(x1+h,1)}. Give 2 decimal places.`,est,`Gradient of the chord = (y₂ − y₁) ÷ (x₂ − x₁). A short chord around the point gives a good estimate of the tangent gradient.`,`y(${rd(x1+h,1)}) = ${rd(f(x1+h),4)}; y(${rd(x1-h,1)}) = ${rd(f(x1-h),4)}; ÷ ${2*h} = ${est}`)}]]);

/* ===== Speed, distance and time ===== */
add('Ratio, Proportion & Rates of Change','Speed, distance and time',[
/* Easy */[
()=>{const s=r(20,70),t=r(2,6);return Q(`A car travels at ${s} km/h for ${t} hours. How far does it go (km)?`,s*t,`Distance = speed × time.`,`${s} × ${t} = ${s*t} km`)},
()=>{const s=r(4,16),t=r(2,5);return Q(`A cyclist travels ${s*t} km in ${t} hours. What is the average speed (km/h)?`,s,`Speed = distance ÷ time.`,`${s*t} ÷ ${t} = ${s} km/h`)},
()=>{const s=pick([40,50,60,80]),d=s*pick([1.5,2.5,0.5,0.75]);return Q(`How long does it take to travel ${d} km at ${s} km/h? Give your answer in minutes.`,d/s*60,`Time = distance ÷ speed (in hours), then × 60 for minutes.`,`${d} ÷ ${s} = ${d/s} hours; × 60 = ${d/s*60} minutes`)},
()=>{let m,s;do{m=pick([15,20,30,45]);s=pick([40,48,60,80])}while((s*m)%60);return Q(`A bus travels at ${s} km/h for ${m} minutes. How far does it travel (km)?`,s*m/60,`Change minutes to hours first: ${m} minutes = ${m/60} h.`,`${m} ÷ 60 = ${m/60} h; ${s} × ${m/60} = ${s*m/60} km`)},
()=>{const s=pick([10,15,20,25]);return Q(`Convert ${s} m/s into km/h.`,s*3.6,`× 3600 to change per second into per hour, ÷ 1000 to change m into km: overall × 3.6.`,`${s} × 3.6 = ${s*3.6} km/h`)}],
/* Moderate */[
()=>{const d1=r(20,60),s1=pick([20,30,40]),d2=r(20,60),s2=pick([40,60,80]);const t=d1/s1+d2/s2;return Q(`A driver travels ${d1} km at ${s1} km/h and then ${d2} km at ${s2} km/h. Find the average speed for the whole journey, to 1 decimal place (km/h).`,rd((d1+d2)/t,1),`Average speed = total distance ÷ total time (NOT the mean of the two speeds).`,`time 1 = ${rd(d1/s1,4)} h; time 2 = ${rd(d2/s2,4)} h; total distance = ${d1+d2}; total time = ${rd(t,4)}; average = ${rd((d1+d2)/t,1)} km/h`)},
()=>{const s=pick([36,54,72,90,108]);return Q(`Convert ${s} km/h into m/s.`,s/3.6,`÷ 3.6 (× 1000 for m, ÷ 3600 for seconds).`,`${s} ÷ 3.6 = ${s/3.6} m/s`)},
()=>{const h=r(9,11),m=pick([15,30,45]),d=r(90,240),s=pick([45,60,75,90]);const t=d/s*60;const end=h*60+m+t;return Q(`A train leaves at ${h}:${String(m).padStart(2,'0')} and travels ${d} km at an average speed of ${s} km/h. At what time does it arrive? How many minutes does the journey take?`.replace(/At what time does it arrive\? /,''),rd(t,1),`Time = distance ÷ speed, then convert hours to minutes.`,`${d} ÷ ${s} = ${rd(d/s,4)} h; × 60 = ${rd(t,1)} minutes`)},
()=>{const d=r(3,12)*100,t=r(2,6)*20;return Q(`A runner covers ${d} m in ${t} seconds. Find the speed in km/h, to 1 decimal place.`,rd(d/t*3.6,1),`Find m/s first, then × 3.6.`,`${d} ÷ ${t} = ${rd(d/t,4)} m/s; × 3.6 = ${rd(d/t*3.6,1)} km/h`)},
()=>{const s=r(2,6),t1=r(1,3);const d=s*t1*10;return Q(`The distance–time graph shows a walk. How fast is the walker going during the first part, in km/h?${svgG({x0:0,x1:5,y0:0,y1:s*t1+2,step:1,lab:s*t1>12?2:1,segs:[[0,0,t1,s*t1],[t1,s*t1,t1+1,s*t1],[t1+1,s*t1,5,0]],xl:'time (h)',yl:'distance (km)'})}`,s,`Speed = gradient of the distance–time graph = distance ÷ time for that section.`,`first section: ${s*t1} km in ${t1} h; ${s*t1} ÷ ${t1} = ${s} km/h`)}],
/* Difficult */[
()=>{const s1=pick([40,50,60]),s2=s1+pick([10,20,30]),d=s1*s2/gcd(s1,s2)/10*pick([1,2]);const dt=(d/s1-d/s2)*60;return Q(`Two cars drive the same ${d} km route. Car A averages ${s1} km/h and car B averages ${s2} km/h. How many minutes sooner does car B arrive?`,rd(dt,2),`Find each journey time, then subtract and convert to minutes.`,`A: ${d} ÷ ${s1} = ${rd(d/s1,4)} h; B: ${d} ÷ ${s2} = ${rd(d/s2,4)} h; difference × 60 = ${rd(dt,2)} min`)},
()=>{const s1=r(40,60),s2=r(50,80),d=(s1+s2)*r(1,3);const t=d/(s1+s2);return Q(`Two towns are ${d} km apart. Car A leaves one town at ${s1} km/h and car B leaves the other town at the same time, travelling towards it at ${s2} km/h. After how many hours do they meet?`,t,`They close the gap at ${s1} + ${s2} = ${s1+s2} km/h.`,`${d} ÷ ${s1+s2} = ${t} hours`)},
()=>{const d=r(4,12),s=pick([10,12,15,20]),sb=pick([4,5,6,8]);const t=d/s*60+d/sb*60;return Q(`${who()} cycles ${d} km to a friend's house at ${s} km/h and walks back the same way at ${sb} km/h. How long does the round trip take, in minutes?`,rd(t,2),`Work out each time separately and add.`,`cycle: ${d} ÷ ${s} = ${rd(d/s,4)} h; walk: ${d} ÷ ${sb} = ${rd(d/sb,4)} h; total = ${rd(t,2)} min`)},
()=>{const L=r(100,300),s=pick([20,25,30]),bl=r(200,800);return Q(`A train ${L} m long travels at ${s} m/s. How long does it take to pass completely through a tunnel ${bl} m long (seconds)? Give 1 decimal place if needed.`,rd((L+bl)/s,1),`The front must travel the tunnel length PLUS the train's own length for the whole train to clear it.`,`distance = ${bl} + ${L} = ${L+bl} m; ${L+bl} ÷ ${s} = ${rd((L+bl)/s,1)} s`)},
()=>{const ds=[r(10,30),r(10,30)],ts=[r(1,2),r(2,3)];const rest=pick([0.5,1]);const avg=(ds[0]+ds[1])/(ts[0]+ts[1]+rest);return Q(`A hiker walks ${ds[0]} km in ${ts[0]} hours, rests for ${rest*60} minutes, then walks ${ds[1]} km in ${ts[1]} hours. What is her average speed for the whole trip including the rest, to 2 decimal places (km/h)?`,rd(avg,2),`Average speed = total distance ÷ total time, and the rest time counts.`,`distance = ${ds[0]+ds[1]}; time = ${ts[0]} + ${rest} + ${ts[1]} = ${ts[0]+rest+ts[1]}; ${rd(avg,2)} km/h`)}],
/* Very Difficult */[
()=>{const s1=pick([40,60]),s2=pick([60,80,120]),h=r(1,3);/* B leaves h hours later, faster, catches A */const t=s1*h/(s2-s1);if(s2<=s1)return Q(`A leaves at 9:00 at 40 km/h. B leaves at 10:00 at 60 km/h on the same road. How many hours after B leaves does B catch A?`,2,'Gap 40 km closes at 20 km/h.','40 ÷ 20 = 2');return Q(`Car A sets off at ${s1} km/h. ${h} hour${h>1?'s':''} later car B sets off from the same place along the same road at ${s2} km/h. How many hours after B sets off does B catch up with A?`,rd(t,4),`When B starts, A is already ${s1*h} km ahead. B closes the gap at ${s2} − ${s1} = ${s2-s1} km/h.`,`gap = ${s1} × ${h} = ${s1*h} km; ${s1*h} ÷ ${s2-s1} = ${rd(t,4)} h`)},
()=>{let v,a,b;do{v=pick([30,40,48,50,60]);a=v-pick([5,6,8,10,12,15]);b=v*a/(2*a-v)}while(2*a<=v||b%1||b>130);const d=r(60,150);return Q(`A car travels ${d} km at ${a} km/h. How fast must it travel for the next ${d} km so that its average speed for the whole ${2*d} km is ${v} km/h?`,b,`Total time needed = ${2*d} ÷ ${v}. Subtract the time already used, then find the speed for the second part.`,`total time = ${rd(2*d/v,4)} h; first part = ${rd(d/a,4)} h; left = ${rd(2*d/v-d/a,4)} h; speed = ${d} ÷ ${rd(2*d/v-d/a,4)} = ${b} km/h`)},
()=>{const w=pick([2,3,4]),s=pick([10,12,15]);/* boat with current */const d=pick([24,30,36,45]);const up=d/(s-w),dn=d/(s+w);return Q(`A boat travels at ${s} km/h in still water. A river flows at ${w} km/h. The boat goes ${d} km upstream and then ${d} km back downstream. How long does the round trip take, in hours? Give 2 decimal places.`,rd(up+dn,2),`Upstream the speed is ${s} − ${w}; downstream it is ${s} + ${w}. Add the two times.`,`up: ${d} ÷ ${s-w} = ${rd(up,4)} h; down: ${d} ÷ ${s+w} = ${rd(dn,4)} h; total = ${rd(up+dn,2)} h`)},
()=>{const d=r(150,400),s=pick([70,80,90]),stops=r(2,4),st=pick([10,15,20]);const arr=d/s*60+stops*st;return Q(`A coach journey of ${d} km is driven at an average speed of ${s} km/h while moving, with ${stops} stops of ${st} minutes each. The coach seats ${r(40,60)} people. How long does the journey take in total, to the nearest minute?`,Math.round(arr),`Driving time = distance ÷ speed. Add the stopping time. The number of seats is not needed.`,`driving = ${d} ÷ ${s} = ${rd(d/s,4)} h = ${rd(d/s*60,2)} min; stops = ${stops*st} min; total = ${rd(arr,2)} ≈ ${Math.round(arr)} min`)},
()=>{const t=r(2,5),a=r(2,5),c=r(1,3);/* reading distance-time from line */const s=pick([12,15,18]);const d=s*t;return Q(`The upper bound of a distance is ${d+0.5} km and the lower bound of the time is ${t-0.05} hours. Find the upper bound of the average speed, to 3 significant figures (km/h).`,sf((d+0.5)/(t-0.05),3),`For the greatest speed, divide the greatest distance by the least time.`,`${d+0.5} ÷ ${rd(t-0.05,2)} = ${sf((d+0.5)/(t-0.05),3)} km/h`)}]]);

/* ===== Density, mass and volume ===== */
add('Ratio, Proportion & Rates of Change','Density, mass and volume',[
/* Easy */[
()=>{const d=r(2,12),v=r(5,40);return Q(`A block has a volume of ${v} cm³ and a density of ${d} g/cm³. What is its mass (g)?`,d*v,`Mass = density × volume.`,`${d} × ${v} = ${d*v} g`)},
()=>{const d=r(2,12),v=r(5,40);return Q(`A rock has a mass of ${d*v} g and a volume of ${v} cm³. What is its density (g/cm³)?`,d,`Density = mass ÷ volume.`,`${d*v} ÷ ${v} = ${d} g/cm³`)},
()=>{const d=r(2,12),v=r(5,40);return Q(`A metal has a density of ${d} g/cm³. A piece of it has a mass of ${d*v} g. What is its volume (cm³)?`,v,`Volume = mass ÷ density.`,`${d*v} ÷ ${d} = ${v} cm³`)},
()=>{const l=r(2,8),w=r(2,6),h=r(2,5),d=r(2,9);return Q(`A cuboid is ${l} cm by ${w} cm by ${h} cm and is made of material with density ${d} g/cm³. What is its mass (g)?`,l*w*h*d,`Find the volume first (l × w × h), then mass = density × volume.`,`volume = ${l*w*h} cm³; mass = ${d} × ${l*w*h} = ${l*w*h*d} g`)},
()=>M(`Which formula is correct? Options: density = mass ÷ volume;  density = volume ÷ mass;  density = mass × volume;  density = mass − volume`,['density = mass ÷ volume','density = volume ÷ mass','density = mass × volume','density = mass − volume'],`Density is the mass in each unit of volume, e.g. grams per cm³.`)],
/* Moderate */[
()=>{const d=pick([0.8,1.2,2.7,7.8,8.9,11.3]),v=r(20,200);return Q(`Find the mass, in kg, of ${v} cm³ of a material with density ${d} g/cm³.`,rd(d*v/1000,4),`Mass in grams = density × volume, then ÷ 1000 for kg.`,`${d} × ${v} = ${rd(d*v,2)} g; ÷ 1000 = ${rd(d*v/1000,4)} kg`)},
()=>{const d=pick([2.7,7.8,8.9,19.3]),m=r(5,50)*10;return N(`Gold has a density of ${d} g/cm³… a bar of metal with density ${d} g/cm³ has mass ${m} g. Find its volume to 3 significant figures (cm³).`.replace(/Gold has a density of [\d.]+ g\/cm³… a/,'A'),sf(m/d,3),'cm³',`Volume = mass ÷ density.`,`${m} ÷ ${d} = ${sf(m/d,3)} cm³`)},
()=>{const d=r(2,9);return Q(`A material has a density of ${d} g/cm³. What is this in kg/m³?`,d*1000,`1 g/cm³ = 1000 kg/m³ (1 m³ = 1 000 000 cm³ and 1 kg = 1000 g).`,`${d} × 1000 = ${d*1000} kg/m³`)},
()=>{const r1=r(2,5),d=pick([2,3,7,8]);const v=4/3*Math.PI*r1**3;return N(`A solid metal sphere has radius ${r1} cm and density ${d} g/cm³. Find its mass to 3 significant figures (g). (Volume of a sphere = (4/3)πr³.)`,sf(v*d,3),'g',`Find the volume with the formula, then multiply by the density.`,`V = (4/3) × π × ${r1}³ = ${rd(v,3)} cm³; mass = ${rd(v,3)} × ${d} = ${sf(v*d,3)} g`)},
()=>{const m1=r(20,60),v1=r(5,15),m2=r(20,60),v2=r(5,15);const d1=m1/v1,d2=m2/v2;return M(`Object A: mass ${m1} g, volume ${v1} cm³. Object B: mass ${m2} g, volume ${v2} cm³. Which has the greater density? Options: ${d1>d2?'A':'B'};  ${d1>d2?'B':'A'};  they are equal;  you cannot tell`,[d1>d2?'A':'B',d1>d2?'B':'A','they are equal','you cannot tell'],`Work out mass ÷ volume for each: A = ${rd(d1,3)}, B = ${rd(d2,3)} g/cm³.`)}],
/* Difficult */[
()=>{const da=pick([2,3,4]),db=pick([6,8,9]),va=r(10,40),vb=r(10,40);const d=(da*va+db*vb)/(va+vb);return Q(`${va} cm³ of liquid A (density ${da} g/cm³) is mixed with ${vb} cm³ of liquid B (density ${db} g/cm³). Find the density of the mixture, to 2 decimal places (g/cm³).`,rd(d,2),`Density of the mixture = total mass ÷ total volume.`,`mass A = ${da*va}; mass B = ${db*vb}; total = ${da*va+db*vb} g; volume = ${va+vb}; density = ${rd(d,2)} g/cm³`)},
()=>{const d=pick([7.8,8.9,2.7]),l=r(10,30),w=r(5,15),h=pick([0.5,1,2]);const m=d*l*w*h;return N(`A metal plate is ${l} cm by ${w} cm by ${h} cm. Its density is ${d} g/cm³. Find its mass in kg, to 3 significant figures.`,sf(m/1000,3),'kg',`Volume = l × w × h in cm³. Mass in g = density × volume, then ÷ 1000.`,`volume = ${rd(l*w*h,2)}; mass = ${rd(m,2)} g = ${sf(m/1000,3)} kg`)},
()=>{const ma=r(100,400),da=pick([2,4,5,8]),mb=r(100,400),db=pick([1,2,4]);const d=(ma+mb)/(ma/da+mb/db);return Q(`An alloy is made from ${ma} g of metal A (density ${da} g/cm³) and ${mb} g of metal B (density ${db} g/cm³). Find the density of the alloy to 2 decimal places (g/cm³).`,rd(d,2),`Find each volume (mass ÷ density), then density = total mass ÷ total volume.`,`vol A = ${rd(ma/da,3)}; vol B = ${rd(mb/db,3)}; total mass ${ma+mb}; total vol ${rd(ma/da+mb/db,3)}; density = ${rd(d,2)}`)},
()=>{const r1=r(2,6),h=r(5,15),d=pick([0.6,0.7,0.8]);const v=Math.PI*r1*r1*h;return N(`A wooden cylinder has radius ${r1} cm and height ${h} cm. Wood has density ${d} g/cm³. Find its mass to 3 significant figures (g).`,sf(v*d,3),'g',`Volume of a cylinder = πr²h. Then mass = density × volume.`,`V = π × ${r1*r1} × ${h} = ${rd(v,3)}; mass = ${sf(v*d,3)} g`)},
()=>{const m=r(2,9)*100,d1=pick([0.8,1]),d2=pick([1.2,1.5]);return Q(`${m} g of a liquid has a volume of ${m/d1} cm³. The same mass of a second liquid has density ${d2} g/cm³. How much smaller is the volume of the second liquid (cm³)? Give 1 decimal place if needed.`,rd(m/d1-m/d2,1),`Find the volume of the second liquid (mass ÷ density) and subtract.`,`second = ${m} ÷ ${d2} = ${rd(m/d2,3)}; difference = ${m/d1} − ${rd(m/d2,3)} = ${rd(m/d1-m/d2,1)}`)}],
/* Very Difficult */[
()=>{const R=r(4,8),r1=r(1,R-2),d=pick([7.8,8.9]);const v=4/3*Math.PI*(R**3-r1**3);return N(`A hollow metal ball has outer radius ${R} cm and inner radius ${r1} cm. The metal has density ${d} g/cm³. Find the mass of the ball in kg, to 3 significant figures.`,sf(v*d/1000,3),'kg',`Volume of metal = volume of outer sphere − volume of hollow centre. Then mass = density × volume, and convert to kg.`,`V = (4/3)π(${R}³ − ${r1}³) = ${rd(v,3)} cm³; mass = ${rd(v*d,2)} g = ${sf(v*d/1000,3)} kg`)},
()=>{const da=pick([2,3]),db=pick([8,9]),D=r(da+1,db-1);/* ratio of volumes x:y such that (da x + db y)/(x+y)=D -> x/y = (db-D)/(D-da) */const g=gcd(db-D,D-da);return X(`Metal A (density ${da} g/cm³) and metal B (density ${db} g/cm³) are combined to make an alloy of density ${D} g/cm³. Find the ratio of the volume of A to the volume of B, in simplest form.`,rat((db-D)/g,(D-da)/g),`Let the volumes be x and y. Then (${da}x + ${db}y) ÷ (x + y) = ${D}. Rearrange to find x : y.`,`${da}x + ${db}y = ${D}x + ${D}y; ${db-D}y = ${D-da}x; x : y = ${db-D} : ${D-da} = ${(db-D)/g} : ${(D-da)/g}`)},
()=>{const l=r(20,40),w=r(10,20),h=r(10,20),fill=pick([0.5,0.75]),d=1;const m=l*w*h*fill*d/1000;return Q(`A fish tank is a cuboid ${l} cm × ${w} cm × ${h} cm. It is ${fill*100}% full of water (density 1 g/cm³). The empty tank weighs ${r(3,9)} kg. What is the mass of the water in kg?`,rd(m,3),`Volume of water = ${fill} × l × w × h. Mass in g = volume (because density is 1), then ÷ 1000. The empty tank's weight is not needed.`,`volume = ${fill} × ${l*w*h} = ${l*w*h*fill} cm³; mass = ${l*w*h*fill} g = ${rd(m,3)} kg`)},
()=>{const d=pick([7.8,8.9,11.3]),m=r(5,20);const v=m*1000/d;const side=Math.cbrt(v);return N(`A solid cube of metal with density ${d} g/cm³ has a mass of ${m} kg. Find the length of one side of the cube, to 3 significant figures (cm).`,sf(side,3),'cm',`Convert the mass to grams, find the volume (mass ÷ density), then take the cube root.`,`${m} kg = ${m*1000} g; V = ${m*1000} ÷ ${d} = ${rd(v,3)} cm³; side = ∛${rd(v,3)} = ${sf(side,3)} cm`)},
()=>{const ma=r(200,500),da=pick([2,4,5]);const mb=r(200,500),db=pick([8,10]);const tot=ma+mb,vtot=ma/da+mb/db;const pc=rd(ma/da/vtot*100,1);return Q(`A mixture contains ${ma} g of substance A (density ${da} g/cm³) and ${mb} g of substance B (density ${db} g/cm³). What percentage of the mixture's VOLUME is substance A? Give 1 decimal place.`,pc,`Find each volume (mass ÷ density), then A's volume as a percentage of the total volume.`,`vol A = ${rd(ma/da,3)}; vol B = ${rd(mb/db,3)}; % = ${rd(ma/da,3)} ÷ ${rd(vtot,3)} × 100 = ${pc}%`)}]]);

/* ===== Pressure ===== */
add('Ratio, Proportion & Rates of Change','Pressure',[
/* Easy */[
()=>{const p=r(2,20),a=r(2,10);return Q(`A force of ${p*a} N acts on an area of ${a} m². What is the pressure (N/m²)?`,p,`Pressure = force ÷ area.`,`${p*a} ÷ ${a} = ${p} N/m²`)},
()=>{const p=r(2,20),a=r(2,10);return Q(`The pressure under a box is ${p} N/m² and the area in contact with the floor is ${a} m². What force does the box exert (N)?`,p*a,`Force = pressure × area.`,`${p} × ${a} = ${p*a} N`)},
()=>{const p=r(2,20),a=r(2,10);return Q(`A force of ${p*a} N produces a pressure of ${p} N/m². What is the area (m²)?`,a,`Area = force ÷ pressure.`,`${p*a} ÷ ${p} = ${a} m²`)},
()=>M(`Which change makes the pressure BIGGER, if the force stays the same? Options: a smaller area;  a bigger area;  a heavier floor;  a longer time`,['a smaller area','a bigger area','a heavier floor','a longer time'],`P = F ÷ A: dividing by a smaller number gives a bigger answer.`),
()=>{const l=r(2,6),w=r(1,4),F=r(2,9)*l*w*10;return Q(`A crate with a base ${l} m by ${w} m weighs ${F} N. What pressure does it exert on the floor (N/m²)?`,F/(l*w),`Find the area of the base, then pressure = force ÷ area.`,`area = ${l*w} m²; ${F} ÷ ${l*w} = ${F/(l*w)} N/m²`)}],
/* Moderate */[
()=>{const F=r(20,90)*10,a=r(10,60);return Q(`A force of ${F} N acts on an area of ${a} cm². What is the pressure in N/cm²? Give 2 decimal places if needed.`,rd(F/a,2),`Pressure = force ÷ area.`,`${F} ÷ ${a} = ${rd(F/a,2)} N/cm²`)},
()=>{const p=r(2,9);return Q(`A pressure of ${p} N/cm² is the same as how many N/m²?`,p*10000,`1 m² = 10 000 cm², so there are 10 000 times as many cm² in a m².`,`${p} × 10 000 = ${p*10000} N/m²`)},
()=>{const m=r(40,90);const g=10;const a=pick([0.02,0.025,0.04,0.05]);return Q(`A person with weight ${m*g} N stands on both feet. Each foot has an area of ${a} m² in contact with the ground. What pressure do they exert (N/m²)?`,m*g/(2*a),`Total area = 2 × ${a} m². Then pressure = force ÷ area.`,`area = ${2*a} m²; ${m*g} ÷ ${2*a} = ${m*g/(2*a)} N/m²`)},
()=>{const F=r(100,500),s=r(2,6);return Q(`A cube with sides ${s} cm weighs ${F} N. What pressure does it exert on a table, in N/cm²? Give 2 decimal places if needed.`,rd(F/(s*s),2),`The contact area is one face: ${s} × ${s} cm².`,`area = ${s*s} cm²; ${F} ÷ ${s*s} = ${rd(F/(s*s),2)} N/cm²`)},
()=>{const F=r(200,800),a1=r(2,5),a2=r(6,10);return Q(`The same box (weight ${F} N) can stand on a face of area ${a1} m² or a face of area ${a2} m². What is the difference between the two pressures, to 1 decimal place (N/m²)?`,rd(F/a1-F/a2,1),`Work out each pressure (force ÷ area) and subtract.`,`${F} ÷ ${a1} = ${rd(F/a1,3)}; ${F} ÷ ${a2} = ${rd(F/a2,3)}; difference = ${rd(F/a1-F/a2,1)}`)}],
/* Difficult */[
()=>{const F=r(20,60)*10,r1=r(2,8);const A=Math.PI*r1*r1;return N(`A cylinder of weight ${F} N stands on its circular base of radius ${r1} cm. Find the pressure on the ground in N/cm², to 3 significant figures.`,sf(F/A,3),'N/cm²',`Area of the base = πr². Pressure = force ÷ area.`,`area = π × ${r1*r1} = ${rd(A,3)} cm²; ${F} ÷ ${rd(A,3)} = ${sf(F/A,3)} N/cm²`)},
()=>{const p=r(2,8)*100,l=r(2,5);return Q(`A square tile must exert a pressure of no more than ${p} N/m² when a force of ${p*l*l} N acts on it. What is the shortest possible side length of the tile (m)?`,l,`Area needed = force ÷ maximum pressure. The tile is square, so square root the area.`,`area = ${p*l*l} ÷ ${p} = ${l*l} m²; side = √${l*l} = ${l} m`)},
()=>{const a=r(2,6),b=r(2,6),c=r(2,6),F=r(100,500);const fs=[a*b,b*c,a*c];const mx=F/Math.min(...fs),mn2=F/Math.max(...fs);return Q(`A cuboid is ${a} cm × ${b} cm × ${c} cm and weighs ${F} N. It can rest on any face. Find the GREATEST pressure it can exert, to 2 decimal places (N/cm²).`,rd(mx,2),`Greatest pressure comes from the SMALLEST face. Find the area of each face.`,`faces: ${fs.join(', ')} cm²; smallest = ${Math.min(...fs)}; ${F} ÷ ${Math.min(...fs)} = ${rd(mx,2)} N/cm²`)},
()=>{const p1=r(200,600),f=pick([2,3,4]);return Q(`The area that a force acts on is multiplied by ${f}, and the force stays the same. The pressure was ${p1} N/m². What is the new pressure (N/m²)? Give 2 decimal places if needed.`,rd(p1/f,2),`Pressure is inversely proportional to area for a fixed force.`,`${p1} ÷ ${f} = ${rd(p1/f,2)}`)},
()=>{const m=r(1,5)*1000,g=10,n=4,a=pick([0.01,0.02,0.025]);return Q(`A car of mass ${m} kg rests on 4 tyres. Each tyre touches the road over ${a} m². Taking weight = mass × 10, find the pressure under each tyre (N/m²).`,m*g/(n*a),`Weight = ${m} × 10 N. Total contact area = 4 × ${a} m².`,`weight = ${m*g} N; area = ${n*a} m²; pressure = ${m*g} ÷ ${n*a} = ${m*g/(n*a)} N/m²`)}],
/* Very Difficult */[
()=>{const s=r(10,30),d=pick([2,2.5,8]);/* cube of side s cm, density d g/cm³; weight = mass(kg)*10 */const m=d*s**3/1000,F=m*10,A=s*s/10000;return N(`A solid cube of side ${s} cm is made from material of density ${d} g/cm³. Taking weight = mass (kg) × 10 N, find the pressure it exerts on the floor in N/m², to 3 significant figures.`,sf(F/A,3),'N/m²',`Volume → mass (g) → mass (kg) → weight (N). The area is one face, converted to m².`,`V = ${s**3} cm³; mass = ${rd(d*s**3,1)} g = ${rd(m,4)} kg; weight = ${rd(F,3)} N; area = ${s*s} cm² = ${A} m²; P = ${sf(F/A,3)} N/m²`)},
()=>{const p=r(2,6)*1000,F=r(1,5)*600;const r1=Math.sqrt(F/(p*Math.PI));return N(`A circular pad must spread a force of ${F} N so that the pressure is exactly ${p} N/m². Find the radius of the pad in cm, to 3 significant figures.`,sf(r1*100,3),'cm',`Area = force ÷ pressure (in m²). Then A = πr², so r = √(A ÷ π). Convert m to cm.`,`A = ${F} ÷ ${p} = ${rd(F/p,5)} m²; r = √(${rd(F/p,5)} ÷ π) = ${rd(r1,5)} m = ${sf(r1*100,3)} cm`)},
()=>{const F1=r(200,500),A1=r(2,5),k=pick([20,25,50]);/* force up k%, area down ... */const a=pick([10,20,25]);const ch=rd(((1+k/100)/(1-a/100)-1)*100,1);return Q(`The force on a surface increases by ${k}% and the area decreases by ${a}%. By what percentage does the pressure increase? Give 1 decimal place.`,ch,`Pressure = F ÷ A. The new pressure = (${1+k/100}F) ÷ (${1-a/100}A).`,`${1+k/100} ÷ ${1-a/100} = ${rd((1+k/100)/(1-a/100),4)}; increase = ${ch}%`)},
()=>{const l=r(20,60),w=r(10,30),p=r(3,9)*100;/* max weight on rectangular base area in cm^2 with pressure N/m^2 */const A=l*w/10000;return Q(`A shelf can withstand a pressure of ${p} N/m². A box with base ${l} cm by ${w} cm is placed on it. What is the maximum weight of the box (N)? Give 2 decimal places if needed.`,rd(p*A,2),`Convert the area to m² (÷ 10 000), then force = pressure × area.`,`area = ${l*w} cm² = ${A} m²; force = ${p} × ${A} = ${rd(p*A,2)} N`)},
()=>{const F=r(400,900),a=r(2,4)*10,b=r(5,9)*10;return Q(`A ${F} N statue can stand on a square base of side ${a} cm or a square base of side ${b} cm. How many times greater is the pressure with the smaller base? Give 2 decimal places.`,rd((b*b)/(a*a),2),`For the same force, pressure ∝ 1/area. Area ∝ side², so the ratio is (${b}/${a})².`,`(${b} ÷ ${a})² = ${rd((b/a)**2,2)}`)}]]);

/* ===== Scale factors ===== */
add('Ratio, Proportion & Rates of Change','Scale factors',[
/* Easy */[
()=>{const k=r(2,5),a=r(2,9);return Q(`A shape is enlarged by scale factor ${k}. One side was ${a} cm. How long is it now (cm)?`,k*a,`Multiply every length by the scale factor.`,`${a} × ${k} = ${k*a} cm`)},
()=>{const a=r(2,9),k=r(2,5);return Q(`A side of ${a} cm becomes ${a*k} cm after an enlargement. What is the scale factor?`,k,`Scale factor = new length ÷ old length.`,`${a*k} ÷ ${a} = ${k}`)},
()=>{const s=pick([25000,50000,100000]),cm=r(2,12);return Q(`A map has scale 1 : ${s.toLocaleString('en-GB')}. Two villages are ${cm} cm apart on the map. How far apart are they in real life, in km?`,cm*s/100000,`Multiply by ${s} to get cm, then ÷ 100 000 to get km.`,`${cm} × ${s} = ${cm*s} cm; = ${cm*s/100000} km`)},
()=>{const s=pick([20,50,100]),m=r(2,9);return Q(`A model car is built to a scale of 1 : ${s}. The real car is ${m} m long. How long is the model, in cm?`,m*100/s,`Change metres to cm (× 100), then divide by ${s}.`,`${m} m = ${m*100} cm; ÷ ${s} = ${m*100/s} cm`)},
()=>{const k=pick([2,3,4]);return M(`A rectangle is enlarged by scale factor ${k}. What happens to its AREA? Options: it is multiplied by ${k*k};  it is multiplied by ${k};  it is multiplied by ${2*k+1};  it stays the same`,[`it is multiplied by ${k*k}`,`it is multiplied by ${k}`,`it is multiplied by ${2*k+1}`,'it stays the same'],`Both the length and the width are multiplied by ${k}, so the area is multiplied by ${k} × ${k}.`)}],
/* Moderate */[
()=>{const k=r(2,5),A=r(3,20);return Q(`Two similar shapes have a length scale factor of ${k}. The smaller one has an area of ${A} cm². What is the area of the larger one (cm²)?`,A*k*k,`Area scale factor = (length scale factor)².`,`${k}² = ${k*k}; ${A} × ${k*k} = ${A*k*k} cm²`)},
()=>{const k=r(2,4),V=r(2,15);return Q(`Two similar solids have a length scale factor of ${k}. The smaller has a volume of ${V} cm³. What is the volume of the larger (cm³)?`,V*k**3,`Volume scale factor = (length scale factor)³.`,`${k}³ = ${k**3}; ${V} × ${k**3} = ${V*k**3} cm³`)},
()=>{const s=pick([20000,25000,50000]),km=r(2,9);return Q(`On a map with scale 1 : ${s.toLocaleString('en-GB')}, how many cm represent ${km} km?`,km*100000/s,`Change km to cm (× 100 000), then divide by ${s}.`,`${km} km = ${km*100000} cm; ÷ ${s} = ${km*100000/s} cm`)},
()=>{const a=r(2,6),k=r(2,4);return Q(`Triangle A has sides ${a}, ${a+1} and ${a+2} cm. Triangle B is similar, and its shortest side is ${a*k} cm. Find B's longest side (cm).`,(a+2)*k,`Find the scale factor from the matching short sides, then apply it to the longest side.`,`k = ${a*k} ÷ ${a} = ${k}; longest = ${a+2} × ${k} = ${(a+2)*k} cm`)},
()=>{const k=pick([0.5,0.25]),a=r(4,20)*4;return Q(`A shape is enlarged by scale factor ${k}. A side of ${a} cm becomes how long (cm)?`,a*k,`A scale factor between 0 and 1 makes the shape smaller.`,`${a} × ${k} = ${a*k} cm`)}],
/* Difficult */[
()=>{const k=r(2,5),A1=r(4,20);return Q(`Two similar shapes have areas ${A1} cm² and ${A1*k*k} cm². What is the length scale factor?`,k,`Area scale factor = ${A1*k*k} ÷ ${A1} = ${k*k}. Length scale factor = √(area scale factor).`,`${k*k}; √${k*k} = ${k}`)},
()=>{const k=r(2,4),V1=r(2,10);return Q(`Two similar bottles have volumes ${V1} litres and ${V1*k**3} litres. The smaller bottle is ${r(10,20)} cm tall… find the length scale factor.`.replace(/The smaller bottle is \d+ cm tall… find/,'Find'),k,`Volume scale factor = ${V1*k**3} ÷ ${V1} = ${k**3}. Length scale factor = cube root.`,`∛${k**3} = ${k}`)},
()=>{const k=r(2,4),A=r(3,12),h=r(5,15);return Q(`Two similar cones: the small one has surface area ${A*k>0?A:A} cm² … the large one has height ${h*k} cm and the small one has height ${h} cm. The small one has volume ${A*10} cm³. Find the volume of the large one (cm³).`.replace(/the small one has surface area \d+ cm² … /,''),A*10*k**3,`Length scale factor = ${h*k} ÷ ${h} = ${k}. Volume scale factor = ${k}³.`,`k = ${k}; ${k}³ = ${k**3}; ${A*10} × ${k**3} = ${A*10*k**3} cm³`)},
()=>{const k=r(2,4),A=r(5,20);const V=A*r(2,6);return Q(`Two similar solids have surface areas ${A} cm² and ${A*k*k} cm². The smaller has volume ${V} cm³. Find the volume of the larger (cm³).`,V*k**3,`From the areas, find the length scale factor (square root). Then cube it for the volume scale factor.`,`area SF = ${k*k}; length SF = ${k}; volume SF = ${k**3}; ${V} × ${k**3} = ${V*k**3} cm³`)},
()=>{const s=pick([2000,2500,5000]),a=r(2,8),b=r(2,8);const real=a*b*s*s/10000;return Q(`A field is a rectangle ${a} cm by ${b} cm on a plan with scale 1 : ${s}. What is its real area in m²?`,real,`Convert each side to real metres first (× ${s}, then ÷ 100), then multiply. (Do not just multiply the plan area by ${s}.)`,`${a} cm → ${a*s/100} m; ${b} cm → ${b*s/100} m; area = ${a*s/100} × ${b*s/100} = ${real} m²`)}],
/* Very Difficult */[
()=>{const k=r(2,4),m=r(2,9)*100,c=r(3,9);/* paint: area scale; cost */return Q(`Two similar statues: the small one is ${c*10} cm tall and the large one is ${c*10*k} cm tall. It takes ${m} ml of paint to cover the small statue. The large statue is solid and weighs ${r(20,80)} kg. How much paint is needed for the large statue (ml)?`,m*k*k,`Paint covers the SURFACE, so use the area scale factor: (length SF)². The weight is not needed.`,`length SF = ${k}; area SF = ${k*k}; ${m} × ${k*k} = ${m*k*k} ml`)},
()=>{const k=pick([2,3]),M1=r(2,8)*100;return Q(`Two similar solid ornaments are made of the same material. Their surface areas are ${r(2,5)*10} cm² and ${k*k} times as much. The smaller has mass ${M1} g. Find the mass of the larger (g).`.replace(/Their surface areas are \d+ cm² and (\d+) times as much/,(m0,t)=>`The larger has ${t} times the surface area of the smaller`),M1*k**3,`Area SF = ${k*k}, so length SF = ${k}. Mass ∝ volume, so use the volume SF ${k}³.`,`length SF = ${k}; volume SF = ${k**3}; ${M1} × ${k**3} = ${M1*k**3} g`)},
()=>{const A=r(2,10)*10,k=pick([1.5,2.5]);return Q(`Two similar jugs have heights in the ratio 2 : ${2*k}. The smaller jug holds ${A} ml. How much does the larger hold (ml)?`,rd(A*k**3,3),`Length SF = ${2*k} ÷ 2 = ${k}. Capacity is a volume, so multiply by ${k}³.`,`${k}³ = ${k**3}; ${A} × ${k**3} = ${rd(A*k**3,3)} ml`)},
()=>{const V1=pick([8,27,64]),V2=pk([125,216,343].filter(v=>v>V1));const A1=r(10,40);const k=Math.cbrt(V2/V1);return Q(`Two similar cylinders have volumes ${V1} cm³ and ${V2} cm³. The smaller has a curved surface area of ${A1} cm². Find the curved surface area of the larger, to 2 decimal places (cm²).`,rd(A1*k*k,2),`Volume SF = ${V2} ÷ ${V1}; length SF = its cube root; area SF = (length SF)².`,`volume SF = ${rd(V2/V1,4)}; length SF = ${rd(k,4)}; area SF = ${rd(k*k,4)}; ${A1} × ${rd(k*k,4)} = ${rd(A1*k*k,2)} cm²`)},
()=>{const p=pick([10,20,25,50]);const inc=rd(((1+p/100)**3-1)*100,1);return Q(`Every length of a solid is increased by ${p}%. By what percentage does its volume increase? Give 1 decimal place.`,inc,`Length SF = ${1+p/100}. Volume SF = (${1+p/100})³.`,`${1+p/100}³ = ${rd((1+p/100)**3,4)}; increase = ${inc}%`)}]]);
})();
